// Üretilen dosya: tool/ozgun/uret.py. Tarih · Arkeoloji ve antik kentler: Anadolu ve dünyadaki kazılar, buluntular (orta).
const ozHistory14Orta = <(String, String, List<String>, String)>[
  ('Göbeklitepe\'nin kurucularının tarım öncesi avcı-toplayıcılar olduğunu düşündüren en güçlü gözlem hangisidir?', 'Dikmelerin yanında gömülü ya da stoklanmış kültür tahılı kalıntılarının değil yabani hayvan kemiklerinin bulunması', ['Alanda çok sayıda sulama kanalı ve tahıl ambarı bulunması', 'Dikmelerde çift sürme sahnelerinin betimlenmesi', 'Evcil sığır sürülerinin ağıl kalıntılarının çoğunlukta olması'], 'Alandaki hayvan kemikleri ağırlıkla yabani türlere (ceylan, yaban öküzü, yaban eşeği) aittir; bu, kuranların avcı-toplayıcı olduğunu düşündürür. Sulama ve sürme izi yoktur.'),
  ('Göbeklitepe dikmelerindeki kabartmalarda en sık görülen betimlemeler hangi grupta toplanır?', 'Yılan, tilki, yaban domuzu, turna gibi vahşi hayvanlar', ['Kral ve tanrı portreleri', 'Savaş arabaları ve ok atan okçular', 'Buğday başakları ve insan hasat sahneleri'], 'Dikmelerde yılan, akrep, tilki, yaban domuzu, turna ve yırtıcı kuş kabartmaları görülür. Yazı, kral portresi ya da hasat sahnesi yoktur; çünkü dönem yazı öncesidir.'),
  ('UNESCO, Göbeklitepe\'yi hangi yıl Dünya Mirası Listesi\'ne almıştır?', '2018', ['2012', '2008', '2021'], 'Göbeklitepe 2018\'de Dünya Mirası Listesi\'ne alınmıştır. Çatalhöyük 2012\'de, Arslantepe ise 2021\'de listeye girmiştir.'),
  ('Göbeklitepe\'nin adı Türkçede hangi anlama gelen bir yer adından türemiştir?', 'Karın (göbek) biçimli yuvarlak tepe', ['Tanrıların oturduğu yüksek ve kutsal tepe', 'Güneşin doğduğu yer', 'Gölgeli kaya'], 'Yöre halkı yamaçtaki yuvarlak tepeye göbek benzetmesiyle "Göbek Tepe" demiştir; Almanca literatürde de "Potbelly Hill" olarak anılır.'),
  ('Şanlıurfa Siverek yakınlarındaki Karahantepe\'nin Göbeklitepe\'den ayrılan en belirgin özelliği hangisidir?', 'Anıtsal yapıda insan başı ve insan figürleri kabartmalarının öne çıkması', ['Hiçbir yapının taştan olmaması', 'Yalnızca Roma dönemine ait olması', 'Denizin kıyısında kurulmuş bir liman olması'], 'Karahantepe\'de özellikle insan başı heykelleri ve insan figürleri öne çıkar; Göbeklitepe\'de ise hayvan kabartmaları ağır basar. İkisi de MÖ 10. binyıl sonu-9. binyıl çevresine tarihlenir.'),
  ('Bir arkeolog, Göbeklitepe\'de gördüğü tören yapılarının nasıl inşa edilebildiğini sorguluyor. Alandaki yaygın görüşe göre bunu sağlayan en önemli etken hangisidir?', 'Çok sayıda insanın ortak işgücü ve örgütlenmesi', ['Metal aletlerle çalışan uzman taş ustalarının varlığı', 'Fil ve at gibi hayvanların çekme gücü', 'Mezopotamya\'dan gelen kralî işçi birlikleri'], 'Alanda metal alet yoktur; dikmeler çakmaktaşı aletlerle yontulup taşınmıştır. Bu iş, bir arada çalışan geniş bir topluluğun örgütlü emeğini gerektirir.'),
  ('Çatalhöyük kazılarını 1993\'te yeniden başlatan ve uzun yıllar sürdüren arkeolog kimdir?', 'Ian Hodder', ['Klaus Schmidt', 'Tahsin Özgüç', 'Kenan Erim'], 'İngiliz arkeolog Ian Hodder, 1993\'ten itibaren yeni bir yöntemsel yaklaşımla ("yansıtıcı arkeoloji") Çatalhöyük\'te çalışmıştır.'),
  ('Çatalhöyük evlerinde ölülerin çoğunlukla nereye gömüldüğü saptanmıştır?', 'Ev içindeki sedirlerin ve tabanın altına', ['Köy dışındaki ortak mezarlıklara ve nehir kıyısına', 'Nehir kıyısındaki kayalıklara', 'Yakınlardaki dağ mağaralarına'], 'Ölüler genellikle yaşanılan evin taban ve platformlarının altına gömülmüştür. Bu, yerleşimin ölü-yaşayan ilişkisini gösteren önemli bir kanıttır.'),
  ('Çatalhöyük evlerinin sıvalı duvarlarında bulunan boğa başı (bukranyum) ve boynuz düzenlemeleri en çok hangi yorumla ilişkilendirilir?', 'Hane içi ritüel ve simgesel anlatım', ['Düşman saldırılarına karşı savunma', 'Yazının ilk örnekleri ve ticari kayıtlar', 'Vergi toplama kayıtları'], 'Boynuzlar ve boğa başları, evlerin sıvalı duvarlarında ritüel/simgesel anlam taşıyan öğeler olarak yorumlanır. Savunma, yazı ya da vergi kaydı olarak yorumlanmaz.'),
  ('Çatalhöyük\'te sokak bulunmaması ve evlere çatıdan girilmesi, kentin hangi özelliğinin sonucu sayılır?', 'Evlerin birbirine bitişik ve sık dokulu kurulması', ['Yerleşimin sık sık su baskınına uğrayan bir ovada kurulması', 'Halkın köleler tarafından yönetilmesi', 'Kerpiç yerine taşın kullanılması'], 'Birbirine bitişik evler arasında geçit kalmadığından hareket damlar üzerinden olmuş, giriş merdivenle çatıdan sağlanmıştır. Yapı malzemesi kerpiçtir.'),
  ('Çatalhöyük\'te bulunan obsidyenin kökeni için en yaygın görüş hangisidir?', 'Kapadokya yöresindeki volkanik kaynaklar', ['Mısır\'daki Aswan granit ocakları ve Nil vadisi', 'Girit adasındaki yataklar', 'Kafkasya\'daki göl yatakları'], 'Obsidyen aletlerin hammaddesi büyük ölçüde Kapadokya volkanlarından (örneğin Göllüdağ ve Nenezi Dağı) getirilmiştir. Bu, yaygın bir ticaret ağına işaret eder.'),
  ('Çatalhöyük hangi yıl UNESCO Dünya Mirası Listesi\'ne alınmıştır?', '2012', ['2016', '2018', '2023'], 'Çatalhöyük Neolitik Höyüğü 2012\'de listeye girmiştir. 2016\'da Ani, 2018\'de Göbeklitepe alındı.'),
  ('Çatalhöyük ve Göbeklitepe aynı dönemin bir sorusu olarak karşılaştırıldığında, yerleşme niteliği açısından hangisi doğrudur?', 'Çatalhöyük binlerce kişilik konut yerleşimi; Göbeklitepe ise ağırlıkla anıtsal tören alanı sayılır', ['İkisi de yalnızca mezarlıktır', 'Çatalhöyük bir liman, Göbeklitepe bir kaledir', 'İkisinde de yazılı belge çok bulunmuştur'], 'Çatalhöyük yoğun bir konut yerleşimi, Göbeklitepe ise anıtsal yapılara sahip bir tören merkezidir. İkisinde de yazılı belge yoktur.'),
  ('Diyarbakır Ergani yakınındaki Çayönü\'nde bulunan ve çok sayıda insan kemiğinin saptandığı yapı hangi adla bilinir?', 'Kafatası Binası', ['Savaş Salonu adıyla anılan büyük tören yapısı', 'Tahıl Ambarı', 'Kral Mezarı'], 'Çayönü\'ndeki "Kafatası Binası"nda yüzlerce bireye ait kemikler bulunmuş ve yapı ritüel amaçlı yorumlanmıştır. Alan Robert Braidwood tarafından kazılmaya başlanmıştır.'),
  ('Burdur yakınındaki Hacılar\'ı 1957-1960 arasında kazan arkeolog kimdir?', 'James Mellaart', ['Kurt Bittel', 'Ekrem Akurgal', 'Seton Lloyd'], 'James Mellaart, Hacılar\'daki kazılarıyla Neolitik ve Kalkolitik boyalı çanak çömleğin Anadolu\'daki gelişimini ortaya koymuştur. Daha sonra Çatalhöyük\'e yönelmiştir.'),
  ('Bir höyükte üst üste yapılmış çok sayıda yapı katına "tabaka" (yerleşme katı) denmesinin arkeolojik açıdan önemi nedir?', 'Kronolojik sıralamanın alt tabakanın daha eski olacağı ilkesine dayanması', ['Üst tabakanın her zaman daha eski olması', 'Tabakaların yalnızca renk farkını göstermesi', 'Tabaka sayısının nüfusu doğrudan vermesi'], 'Stratigrafide, bozulmamış durumda alttaki katmanlar üsttekilerden daha eskidir. Böylece buluntular göreli olarak sıralanabilir.'),
  ('Antalya yakınlarındaki hangi mağara, Alt Paleolitik\'ten Neolitik\'e uzanan kesintisiz bir yerleşme dizisi vermesiyle Türkiye\'de Paleolitik araştırmaların temel alanı sayılır?', 'Karain Mağarası', ['Yarımburgaz Mağarası', 'Dupnisa Mağarası', 'Damlataş Mağarası'], 'Karain, 1940\'ların ortasında Kılıç Kökten tarafından tanıtılmış ve uzun yıllar kazılmıştır; yüz binlerce yıllık bir kültür dizisi içerir. Yarımburgaz İstanbul\'dadır.'),
  ('Hamit Zübeyr Koşay ve Remzi Oğuz Arık\'ın Atatürk\'ün isteğiyle Türk Tarih Kurumu adına 1935\'te kazmaya başladığı Çorum\'daki höyük hangisidir?', 'Alacahöyük', ['Kültepe', 'Hattuşa', 'Gordion'], 'Alacahöyük, Cumhuriyet döneminde Türk arkeologlarca yürütülen ilk büyük kazılardan biridir. Hitit başkenti Hattuşa ise Boğazkale\'dedir.'),
  ('Anadolu\'da Demirçağ öncesinde "Hatti" kültürüne bağlanan Horoztepe ve Alacahöyük mezarlarında bulunan metal eserlerin ortak özelliği nedir?', 'Tunç ve altın işçiliğinde yüksek bir ustalık', ['Demirden yapılmış silahlar', 'Kil tabletlere yazılmış yazıtlar', 'Bol miktarda sikke'], 'Bu mezarlardan çıkan bronz, altın ve gümüş eşyalar Erken Tunç Çağı metal işçiliğini gösterir. Sikke Lidya\'da MÖ 7. yüzyıldan sonra ortaya çıkmıştır.'),
  ('Troya\'nın yerini Hisarlık Tepesi olarak belirleyip Heinrich Schliemann\'ı buraya yönlendiren, Çanakkale\'de yaşayan İngiliz kimdir?', 'Frank Calvert', ['Charles Newton', 'Arthur Evans', 'Austen Layard'], 'Frank Calvert, Hisarlık\'ın bir bölümüne sahipti ve burada deneme kazıları yapmıştı; Schliemann\'ı bu tepeye yönlendirdi. Evans Knossos\'u, Layard Nimrud\'u kazmıştır.'),
  ('Schliemann\'ın Troya\'da tepenin ortasından geniş bir hendek açarak çalışması arkeoloji açısından hangi sonucu doğurmuştur?', 'Üst katmanlardaki Troya yapılarının büyük bölümünün zarar görmesine', ['Troya\'nın bütün yazıtlarının bulunmasına', 'Alanın tamamen korunmasına', 'Sadece Roma yapılarının ortaya çıkmasına'], 'Schliemann Homeros\'un Troya\'sını ararken derin bir kesit açtı ve bunun sırasında üstteki daha geç katmanları tahrip etti. Bu yüzden yöntemi eleştirilir.'),
  ('Troya\'nın Dünya Mirası Listesi\'ne alındığı yıl aşağıdakilerden hangisidir?', '1998', ['1985', '2005', '2012'], 'Troya Arkeolojik Alanı 1998\'de listeye alınmıştır. Hattuşa 1986\'da, Efes 2015\'te girmiştir.'),
  ('Troya VI surları ve kulelerinin sağlamlığı, kentin Ege ticareti ve gücüyle ilgili olarak ne düşündürür?', 'Zengin ve iyi savunulan bir merkez olduğunu', ['Kentin küçük ve savunmasız bir köy olduğunu', 'Kentte hiç savaş yaşanmadığını', 'Kentin denizden uzakta olduğunu'], 'Büyük kule ve kalın duvarlarla donatılmış Troya VI, güçlü, zengin ve örgütlü bir yönetimin varlığına işaret eder.'),
  ('Hattuşa\'da bulunan Kadeş Antlaşması tabletinin Hitit nüshası hangi dille kaleme alınmıştır?', 'Akadca', ['Latince', 'Aramice', 'Yunanca'], 'Dönemin uluslararası diplomasi dili olan Akadca, Hitit ile Mısır arasındaki antlaşmada kullanılmıştır. Böylece taraflar ortak bir yazı ve dil üzerinden anlaşabilmiştir.'),
  ('Hattuşa\'da bulunan tabletlerde Hititçenin yanında Hattice, Luvice, Palaca ve Hurrice gibi dillerin de yer alması neyi gösterir?', 'Başkentin çok dilli ve çok kültürlü yapısını', ['Kentin yalnızca bir dilin konuşulduğunu', 'Tabletlerin tamamının sonradan kopyalandığını', 'Hitit tablet arşivinin Mısır\'dan getirildiğini'], 'Farklı dillerdeki ritüel ve dua metinleri, Hitit devletinde çeşitli halkların kültürlerinin birleştiğini gösterir.'),
  ('Hattuşa\'daki Aslanlı Kapı ve Kral Kapısı gibi anıtsal yapılar, Hitit devletinin hangi yönünü yansıtır?', 'Güçlü merkezî yönetimin ve savunma mimarisindeki ustalığın', ['Denizcilikteki üstünlüğün', 'Yazının henüz bilinmediğinin', 'Kentin göçebe olduğunun'], 'Kapı kulelerinde kabartma ve devasa blokların kullanılması kralın otoritesini ve gelişmiş mimariyi gösterir.'),
  ('Karatepe-Aslantaş kazılarının Türk tarafındaki en bilinen yöneticisi kimdir?', 'Halet Çambel', ['Nimet Özgüç', 'Remzi Oğuz Arık', 'Ekrem Akurgal'], 'Halet Çambel, Alman Helmuth Bossert ile birlikte Karatepe\'de çalışmış ve açık hava müzesini kuran isim olmuştur.'),
  ('Kültepe\'de çıkan binlerce kil tabletin çoğunun Asur dilinde yazılması neyi gösterir?', 'Asurlu tüccarların Anadolu\'da yerleşik ticaret koloni ağı kurduğunu', ['Hititlerin Asur\'u fethettiğini', 'Kültepe\'nin bir Asur başkenti olduğunu', 'Tabletlerin Mısır\'dan getirildiğini'], 'Eski Asurca tabletler, Aşur kentinden gelen tüccarların Kaniş gibi merkezlerde ticaret yaptığını belgeler.'),
  ('Kültepe kazılarında bulunan Asur tüccar arşivlerinin ticari malları hangi seçenekte doğru verilmiştir?', 'Anadolu\'ya kalay ve tekstil, Asur\'a gümüş ve altın', ['Anadolu\'dan tahıl ve zeytin, Asur\'dan gümüş ve altın', 'Anadolu\'dan demir, Asur\'dan cam', 'Anadolu\'dan tuz, Asur\'dan baharat'], 'Asurlular Anadolu\'ya kalay ve kumaş getirmiş, karşılığında gümüş ve altın almışlardır.'),
  ('Kültepe\'nin kazı yöneticisi olarak 1948\'den başlayarak uzun yıllar çalışan Türk arkeolog kimdir?', 'Tahsin Özgüç', ['Halet Çambel', 'Ekrem Akurgal', 'Hamit Zübeyr Koşay'], 'Tahsin Özgüç Kültepe\'yi kazmış, Asur kolonilerinin Anadolu\'daki yerini belgelemiştir.'),
  ('Kültepe\'de bulunan kil tabletlerin kil zarfa konup mühürlenmesi hangi amaca hizmet ederdi?', 'Mektup ve belge gizliliğini ve güvenliğini sağlamaya', ['Yalnızca süs amacıyla ve tanrılara adak olarak', 'Tabletleri ısıtmaya', 'Çocukların eğitimi için'], 'Kil zarf ve mühür, içindeki belgenin değiştirilmediğinden emin olmayı sağlar.'),
  ('Asur ticaret kolonilerindeki kadın tüccarların mektuplaşması, Anadolu\'daki bu toplumun hangi özelliğini gösterir?', 'Kadınların ticari ve hukuki hayatta etkin rol oynadığını', ['Kadınların hiç yazı bilmediğini ve ticarete katılmadığını', 'Kadınların yalnızca savaşa katıldığını', 'Kadınların köle olduğunu'], 'Tabletlerde kadınların ticaret yaptığı, mal gönderdiği ve davalara katıldığı görülür.'),
  ('Gordion kazılarını 1950\'den itibaren yöneten Pennsylvania Üniversitesi arkeoloğu kimdir?', 'Rodney Young', ['Carl Blegen', 'Leonard Woolley', 'Seton Lloyd'], 'Rodney Young Gordion\'da Midas Tümülüsü\'nü açmış ve Frig dönemini aydınlatmıştır.'),
  ('Midas Tümülüsü\'nde bulunan çok sayıda bronz kazan, kase ve ahşap mobilya Frig toplumu hakkında ne gösterir?', 'Ziyafet geleneğinin ve mobilya işçiliğinin gelişkinliğini', ['Kentin göçebe olduğunu', 'Yazının bilinmediğini', 'Dinin olmadığını'], 'Mezarda şölen takımları ve masalar bulunması, bu çağda ziyafetin ve ahşap işçiliğinin gelişmiş olduğunu gösterir.'),
  ('Eskişehir ve Afyon yöresinde Frig Vadisi\'ndeki en tanınmış kaya anıtı hangisidir?', 'Midas Anıtı', ['Arslankapı', 'Nemrut Heykelleri', 'Kızlar Manastırı'], 'Midas Anıtı, kaya yüzüne oyulmuş geometrik motiflerle bezeli bir cephedir.'),
  ('Frig alfabesinin kökeni için en yaygın görüş hangisidir?', 'Fenike alfabesinden türemiş olması', ['Çivi yazısından türemiş ve sonradan sadeleşmiş olması', 'Hiyeroglifin devamı olması', 'Latin alfabesinden alınması'], 'Frig yazısı, Fenike alfabesinden alınmış ve Yunanca ile benzerlik gösterir.'),
  ('Frigler\'in Anadolu\'daki ana tanrıçası olarak bilinen ve daha sonra Greklerce de benimsenen tanrıça kimdir?', 'Kybele (Matar)', ['Artemis (Efes\'in çok memeli tanrıçası)', 'Hera', 'Athena'], 'Kybele, Frig ana tanrıçasıdır; kültü Yunan ve Roma dünyasına yayılmıştır.'),
  ('Urartuların çivi yazısı hangi uygarlığın yazı sisteminden uyarlanmıştır?', 'Asur çivi yazısından', ['Mısır hiyerogliflerinden', 'Fenike alfabesinden', 'Hint Brahmi yazısından'], 'Urartu yazıcıları yerel dillerini yazmak için Asur çivi yazısını uyarlamışlardır; bu yüzden ilk yazıtlar Asurcadır.'),
  ('Van Kalesi\'ndeki Horhor Kitabeleri ve Şamram (Menua) Kanalı\'nın ortak noktası aşağıdakilerden hangisidir?', 'İkisi de Urartu dönemi yapı ve yazıtlarıdır', ['İkisi de Hitit dönemine ait yazıt ve su yapılarıdır', 'İkisi de Bizans yapılarıdır', 'İkisi de Selçuklu eserleridir'], 'Horhor Kitabeleri Argişti\'nin yıllıklarını, Şamram Kanalı ise Menua döneminde yapılan suyolunu temsil eder. İkisi de Urartu dönemidir.'),
  ('Urartular madenciliği ve bronz işçiliğinde ilerlemişti. Bu durum arkeolojik açıdan hangi buluntularla kanıtlanır?', 'Aslan başlı kazanlar, bronz kemerler ve kabartmalı kalkanlar', ['Mermer heykeller ve mozaikler', 'Cam şişeler ve sikkeler', 'Taş tabletler ve papirüs'], 'Urartu mezarları ve depolarından çıkan bronz kazan, kalkan ve kemerler bu ustalığı gösterir. Sikke Lidya\'dandır.'),
  ('Sardes (Manisa) antik kentinde yıllardır kazı yapan ve 1958\'den itibaren çalışan Amerikan heyeti hangi üniversitelerle ilişkilidir?', 'Harvard ve Cornell', ['Yale ve Princeton', 'Oxford ve Cambridge', 'Berlin ve Münih'], 'Sardis Expedition Harvard ve Cornell üniversitelerince yürütülmüştür ve Lidya başkentini aydınlatmıştır.'),
  ('Manisa\'daki Bin Tepe Tümülüsleri\'nde Herodot\'un Alyattes\'e atfettiği büyük mezar neyi gösterir?', 'Lidya krallarının anıtsal mezar geleneğini', ['Hitit krallarının gömüldüğü büyük kraliyet nekropolünü', 'Roma imparatorlarının mezarlığını', 'Frig kralının sarayını'], 'Bin Tepe\'deki büyük höyükler Lidya krallarının gömüldüğü anıtsal tümülüslerdir.'),
  ('Efes kazılarını 1895\'ten beri sürdüren kurum aşağıdakilerden hangisidir?', 'Avusturya Arkeoloji Enstitüsü', ['Alman Arkeoloji Enstitüsü, Berlin merkezli kurum', 'Fransız Okulu', 'İngiliz Enstitüsü'], 'Efes\'te 1895\'ten itibaren Avusturya Arkeoloji Enstitüsü çalışmaktadır; ilk başkanı Otto Benndorf\'tur.'),
  ('Efes\'teki Celsus Kütüphanesi\'nin ayrıcalıklı yanı nedir?', 'İçinde Celsus\'un mezarının bulunması', ['Papirüs yerine parşömen kullanılan ilk kütüphane', 'Tek kata sahip olması', 'Hiç yazı bulunmaması'], 'Kütüphane, Celsus Polemaeanus\'un anısına yapılmış ve mezarı içindedir. Binanın cephesi 1970\'lerde yeniden dikilmiştir.'),
  ('Efes\'teki Yamaç Evleri\'nde bulunan fresk ve mozaikler arkeologlara neyi gösterir?', 'Roma dönemi zengin ailelerinin yaşam biçimini', ['Neolitik dönem avcı-toplayıcıların günlük yaşamını', 'Hitit kral saraylarını', 'İlk Türk yerleşimlerini'], 'Yamaç Evleri, kentin zengin kesiminin yaşam kalitesini, süslemelerini ve ekonomisini gösteren konut kalıntılarıdır.'),
  ('Efes Büyük Tiyatrosu\'nun yaklaşık yirmi dört bin kişilik kapasiteye sahip olması hangi sonucu destekler?', 'Efes\'in büyük nüfuslu ve önemli bir kent olduğunu', ['Efes\'in küçük bir köy olduğunu', 'Tiyatronun yalnızca saray için yapıldığını', 'Kentin terk edilmiş olduğunu'], 'Büyük tiyatro, kentin nüfus ve kültürel etkinlik düzeyini gösterir; Efes Roma\'nın Asya eyaletinin önemli merkeziydi.'),
  ('Efes\'in limanının zamanla işlevini yitirip kentin gerilemesinin başlıca doğal nedeni nedir?', 'Küçük Menderes\'in taşıdığı alüvyonla limanın dolması', ['Depremde denize gömülmesi', 'Büyük bir kuraklık', 'Nehrin yön değiştirmesiyle kentin sular altında kalması'], 'Çayın getirdiği alüvyon limanı doldurmuş, kent denizle bağlantısını kaybederek önemini yitirmiştir.'),
  ('Bergama\'daki Zeus Altarı\'nı Berlin\'e götüren kazı çalışmalarını yürüten Alman mühendis kimdir?', 'Carl Humann', ['Heinrich Schliemann', 'Theodor Wiegand', 'Wilhelm Dörpfeld'], 'Humann, 1878\'de başladığı Bergama kazılarıyla Büyük Altar\'ı ortaya çıkarmıştır. Altarın kabartmaları Osmanlı\'dan izinle Berlin\'e taşınmıştır.'),
  ('Pergamon Zeus Altarı\'nın friz kabartmalarında hangi konu işlenmiştir?', 'Tanrılar ile devlerin savaşı', ['Truva Savaşı ve Aşil ile Hektor\'un düellosu', 'Roma\'nın kuruluşu', 'Büyük İskender\'in seferleri'], 'Büyük Altar\'ın frizi Olimpos tanrılarının devlerle savaşını dramatik bir anlatımla gösterir.'),
  ('Bergama\'daki Asklepion\'un bilim tarihindeki önemi nedir?', 'Hekim Galenos\'un çalıştığı bir sağlık merkezi olması', ['Avrupa\'nın ilk üniversitesinin Roma\'da kurulduğu yer', 'Pers kralının sarayı olması', 'Frig başkenti olması'], 'Asklepion tıp tanrısına adanmış bir sağlık merkeziydi; Galenos burada eğitim görmüş ve çalışmıştır.'),
  ('Milet\'in Pers Savaşları\'ndan sonra yeniden kurulurken uygulanan ızgara planı (Hippodamos düzeni) kentsel gelişimde neyi temsil eder?', 'Önceden tasarlanmış, birbirini dik kesen sokak düzenini', ['Surların doğal tepeye uyduğu düzensiz yerleşmeyi', 'Kent merkezinde tek ana yol bulunmasını', 'Evlerin kerpiç yığınlarından oluşmasını'], 'Hippodamos\'a atfedilen düzen, caddelerin dik açıyla kesiştiği planlı kentleşmeyi gösterir. Milet ve Priene bu anlayışın örnekleridir.'),
  ('Milet ve Didim kazılarını 1899\'dan itibaren yürüten Alman arkeolog kimdir?', 'Theodor Wiegand', ['Carl Humann', 'Heinrich Schliemann', 'Ernst Curtius'], 'Wiegand, Milet\'te ve Didim\'de çalışmış, Pazar Kapısı\'nı Berlin\'e götürmüştür. Humann Bergama\'da çalışmıştır.'),
  ('Milet Pazar Kapısı\'nın cephesi hangi müzede yeniden kurulmuştur?', 'Berlin\'deki Pergamon Müzesi', ['İstanbul Arkeoloji Müzesi', 'British Museum', 'Louvre Müzesi'], 'Kapının cephesi Milet\'ten Berlin\'e götürülmüş ve Pergamon Müzesi\'nde yeniden kurulmuştur.'),
  ('Priene\'nin kıyıdan uzakta kalması ve önceki liman işlevini yitirmesinin başlıca nedeni nedir?', 'Büyük Menderes\'in taşıdığı alüvyonla koyun dolması', ['Kentin büyük bir depremle çökmesi ve halkın başka kente göç etmesi', 'Pers işgali', 'Bir salgın hastalık'], 'Menderes\'in alüvyonları koyu doldurmuş, kıyı çizgisi uzaklaşmıştır. Aynı süreç Milet ve Efes için de geçerlidir.'),
  ('Xanthos\'tan British Museum\'a taşınan anıtlar arasında yer alan Nereid Anıtı\'nı Londra\'ya götüren kişi kimdir?', 'Charles Fellows', ['Charles Newton', 'John Wood', 'Austen Layard'], 'Charles Fellows, 1840\'larda Xanthos\'tan Likya anıtlarını İngiltere\'ye taşıtmıştır. Newton Halikarnassos\'ta çalışmıştır.'),
  ('Myra (Demre) antik kentini tanıtan en önemli kaya yapıları nelerdir?', 'Kayalara oyulmuş mezarlar ve Roma tiyatrosu', ['Hitit kaya kabartmaları ve kral heykelleri', 'Neolitik mağaralar', 'Selçuklu kervansarayları'], 'Myra\'da kayalıklara oyulmuş Likya mezarları ve büyük tiyatro dikkat çeker. Kentin adı Aziz Nikolaos ile de anılır.'),
  ('Likya kaya mezarlarında ahşap mimariyi taşa aktaran bir görünüm bulunması neyi düşündürür?', 'Taş işçiliğinden önce ahşap yapıların yaygın olduğunu', ['Hiç ahşap kullanılmadığını ve taş mimarinin yerli olduğunu', 'Mezarların sonradan yapıldığını', 'Sadece Romalıların yaptığını'], 'Kaya mezarlarının cephelerindeki kiriş ve kapı biçimleri ahşap ev mimarisini taklit eder; bu da yerel inşaat geleneğini gösterir.'),
  ('Halikarnassos Mausoleionu\'nu 1856-1858\'de kazan ve heykellerini British Museum\'a götüren arkeolog kimdir?', 'Charles Newton', ['Austen Layard', 'Charles Fellows', 'Arthur Evans'], 'Newton\'ın Bodrum\'daki kazıları, Mausoleion\'dan çok sayıda heykel ve friz ele geçirmiştir. Evans Girit\'te çalışmıştır.'),
  ('Mausoleion bugün neden büyük oranda yok olmuştur?', 'Depremlerle yıkılması ve taşlarının Bodrum Kalesi\'nde kullanılması', ['Büyük bir yangında kül olması', 'Nil taşkınıyla yıkılması', 'Savaşta Romalılarca yıkılması'], 'Anıt, depremlerle yıkıldıktan sonra taşları Şövalyelerce kale yapımında kullanılmıştır. Bugün yalnızca temel kalıntısı görülür.'),
  ('Mausolos\'un Karya başkentini Halikarnassos\'a taşıması, bu bölgenin hangi yönünü güçlendirmiştir?', 'Ege kıyısındaki liman ve deniz hâkimiyetini', ['Orta Anadolu\'daki tarım topraklarının denetimini', 'Kafkasya ticaretini', 'Nil bağlantısını'], 'Halikarnassos kıyıda ve doğal limana sahip olduğundan Karya yönetimi deniz ticaretini ve savunmayı güçlendirmiştir.'),
  ('Aydın\'daki Afrodisias\'ta çok sayıda heykel atölyesi bulunması, kentin hangi özelliğini gösterir?', 'Mermer ocaklarına yakınlığı ve heykeltıraşlık okulunu', ['Büyük ölçekli tahıl üretimi ve ihracatını yapabilmesini sağlayan düzeni', 'Ağır sanayi merkezi olmasını', 'Bir liman kenti olmasını'], 'Afrodisias yakınlarındaki mermer yatakları, kente ünlü bir heykel ekolü kazandırmıştır.'),
  ('Afrodisias\'ta 1961\'den başlayarak uzun yıllar kazı yürüten ve alanın bugünkü ününü sağlayan arkeolog kimdir?', 'Kenan Erim', ['Ekrem Akurgal', 'Tahsin Özgüç', 'Nezih Fıratlı'], 'Erim, New York Üniversitesi adına Afrodisias\'ı yıllarca kazmış ve mezarı kent içinde yer almıştır.'),
  ('Afrodisias\'taki stadyum aşağıdaki hangi özelliğiyle bilinir?', 'Antik dünyanın en iyi korunmuş stadyumlarından biri olması', ['Hiç seyirci almaması', 'Sadece Hitit döneminde kullanılması', 'Denizin altında kalması'], 'Stadyum yaklaşık 30.000 kişilik kapasiteyle iyi korunmuştur. Roma dönemi spor ve gösteri hayatının önemli örneğidir.'),
  ('Afrodisias hangi yıl UNESCO Dünya Mirası Listesi\'ne girmiştir?', '2017', ['2023', '2008', '2012'], 'Afrodisias, 2017\'de listeye girmiştir; kentin mermer ocakları da korunan alana dahildir.'),
  ('Aspendos Tiyatrosu\'nun antik çağdan günümüze iyi korunmuş kalması en çok hangi gelişmeyle ilişkilendirilir?', 'Selçuklu döneminde kervansaray ve saray olarak kullanılması', ['Roma döneminde yıkılıp ardından yeniden inşa edilmesi', 'Mısırlılarca kil tabakasıyla örtülmesi', 'Hititlerin kutsal alan saymasıyla kimsenin dokunmaması'], 'Aspendos Tiyatrosu\'nun Selçuklu döneminde kullanılması bakım görmesini sağlamış, bu da yapının sağlam kalmasına yol açmıştır. Yapının mimarı geleneksel olarak Zenon ailesine bağlanır.'),
  ('Perge\'de kentin ana caddesinin ortasından akan su kanalı nasıl bir kentsel düzeni gösterir?', 'Su yönetimine önem veren planlı bir Roma kenti', ['Su kıtlığı çeken ve planlı olmayan küçük bir kasaba', 'Askerî kamp düzenini', 'Mısır tarzı tapınak yolunu'], 'Perge\'de sütunlu cadde boyunca akan su kanalı, kentsel planlama ve su mühendisliğindeki gelişmişliği gösterir.'),
  ('Side antik kentinin adı Anadolu dillerinden birinde hangi anlama gelir?', 'Nar', ['Güneş', 'Su', 'Dağ'], 'Side adı "nar" anlamına gelir; kentin sikkelerinde nar motifi sıkça görülür.'),
  ('Nemrut Dağı Tümülüsü\'ndeki dev heykelleri yaptıran Kommagene kralı kimdir?', 'I. Antiochos Theos', ['II. Mithradates', 'Büyük İskender', 'Seleukos Nikator'], 'Kommagene kralı I. Antiochos, mezarını dev heykellerle çevrelemiştir. Heykellerde Yunan ve Pers tanrıları birleşmiştir.'),
  ('Nemrut Dağı\'nı UNESCO Dünya Mirası\'na kazandıran yıl aşağıdakilerden hangisidir?', '1987', ['1975', '1994', '2004'], 'Nemrut Dağı 1987\'de listeye girmiştir. Bu, Türkiye\'nin ilk girişlerinden biridir.'),
  ('Fırat kıyısındaki Zeugma\'nın kurtarma kazılarına neden gerek duyulmuştur?', 'Birecik Barajı\'nın kenti sular altında bırakacak olması', ['Bir depremin kenti yıkması', 'Büyük bir yangının çıkması', 'Savaş nedeniyle bölgenin boşaltılması'], 'Baraj gölü kentin bir bölümünü kapattığından, ele geçirilebilen mozaikler ve yapılar kurtarma kazılarıyla çıkarılmıştır.'),
  ('Kars\'taki Ani Harabeleri hangi yıl UNESCO Dünya Mirası Listesi\'ne alınmıştır?', '2016', ['2014', '2010', '2022'], 'Ani Arkeolojik Alanı 2016\'da listeye girmiştir. Bagratlı başkenti olan Ani, çok sayıda Ermeni ve Selçuklu yapısı barındırır.'),
  ('İstanbul Yenikapı\'daki Marmaray kazılarında bulunan Theodosius Limanı ve batıklar bilime ne kazandırmıştır?', 'Bizans gemicilik tarihine dair çok sayıda batık ve eser', ['Hitit saray arşivini', 'Çatalhöyük benzeri höyük', 'Likya mezarları'], 'Yenikapı\'da çok sayıda batık ve Neolitik yerleşim kalıntısı çıkmıştır; bunlar kentin deniz tarihini aydınlatır.'),
  ('Yenikapı kazılarında ortaya çıkan Neolitik yerleşim izleri İstanbul tarihi açısından neyi gösterir?', 'Kentin yerleşim geçmişinin Roma\'dan çok daha eski, yaklaşık 8500 yıl öncesine uzandığını', ['Kentin Roma döneminde kurulduğunu', 'Boğazı henüz kimsenin geçmediğini', 'İstanbul\'un hiç depremden etkilenmediğini'], 'Yenikapı\'daki Neolitik buluntular, İstanbul\'daki en erken yerleşimin yaklaşık 8500 yıl öncesine gittiğini gösterir.'),
  ('Arslantepe Höyüğü (Malatya) hangi yıl UNESCO Dünya Mirası Listesi\'ne alınmıştır?', '2021', ['2012', '2016', '2023'], 'Arslantepe Höyüğü, erken devlet oluşumunu gösteren kalıntılarıyla 2021\'de listeye girmiştir.'),
  ('1887\'de Sayda\'da (Sidon) kral mezarlığını kazarak İskender Lahdi\'ni İstanbul\'a getiren, Müze-i Hümayun müdürü olan Osmanlı ressam ve arkeolog kimdir?', 'Osman Hamdi Bey', ['Halil Edhem Eldem', 'Şeker Ahmed Paşa', 'Hamit Zübeyr Koşay'], 'Osman Hamdi Bey, Sayda kazısıyla bulduğu lahitleri İstanbul\'a taşımış, İstanbul Arkeoloji Müzeleri\'nin kuruluşunda belirleyici olmuştur. Koşay Cumhuriyet dönemi arkeoloğudur.'),
  ('Osmanlı\'da 1884 tarihli Asar-ı Atika Nizamnamesi\'nin arkeoloji tarihindeki önemi nedir?', 'Kazı buluntularının devlet malı sayılıp yurt dışına çıkarılmasının sınırlanması', ['Kazıların tamamen yasaklanması', 'Yabancı müzelere eser satışının serbest bırakılması', 'Müzelerin özel kişilere devredilmesi'], '1884 nizamnamesi, eski eserlerin devlete ait olduğunu belirleyerek eser kaçakçılığına karşı yasal çerçeve oluşturmuştur.'),
  ('Ankara\'daki Anadolu Medeniyetleri Müzesi\'nin 1997\'de kazandığı uluslararası ödül aşağıdakilerden hangisidir?', 'Avrupa Yılın Müzesi Ödülü', ['Nobel Barış Ödülü', 'Pritzker Ödülü', 'Altın Palmiye'], 'Müze, Mahmut Paşa Bedesteni ve Kurşunlu Han\'daki sergileriyle 1997\'de Avrupa Yılın Müzesi seçilmiştir.'),
  ('Keban ve Atatürk gibi barajlar yapılmadan önce arkeologların yürüttüğü çalışmalara ne ad verilir?', 'Kurtarma kazısı', ['Yüzey araştırması', 'Deneysel arkeoloji', 'Su altı kazısı'], 'Baraj gölü altında kalacak alanlarda eserleri belgeleyip kurtarmak için yapılan kazılara kurtarma kazısı denir. Bunlar yüzey araştırmasından farklıdır.'),
  ('Kaçak kazıların arkeoloji bilimine en büyük zararı nedir?', 'Eserlerin bağlamını (bulundukları yeri ve tabakayı) yok etmesi', ['Eserlerin fiyatını düşürmesi', 'Kazı ekibinin sayısını artırması', 'Müzelerin çoğalması'], 'Bağlamından koparılan eser, tarihlendirme ve yorum için gerekli bilgiyi kaybeder. Bu yüzden kaçak kazı geri dönüşsüz bir tahribat sayılır.'),
  ('Giza\'daki piramit işçi köyünün kazılarıyla ulaşılan sonuç hangisidir?', 'İşçilerin beslenen, bakımı yapılan ücretli emekçiler olduğu', ['İşçilerin tamamının köle olduğu', 'Piramitlerin uzaylılarca yapıldığı', 'Kentin hiç yaşayan olmadığı'], 'Fırın, ekmek ve hayvan kemikleri ile işçi mezarları, işçilerin iyi beslendiğini ve onurlu gömüldüğünü gösterir.'),
  ('Kheops (Khufu) Piramidi yakınında 1954\'te bulunan ve parçalar hâlinde gömülü olan ahşap yapı nedir?', 'Khufu\'nun güneş gemisi', ['Nil\'de balıkçıların kullandığı küçük kayık', 'Tutankhamon\'un arabası', 'Firavunun tahtı'], 'Khufu\'nun gemisi parçalar hâlinde çukura gömülmüş hâlde bulunmuş, yeniden birleştirilmiştir.'),
  ('Abu Simbel tapınaklarının 1960\'larda kesilip yukarı taşınmasının nedeni nedir?', 'Aswan Yüksek Barajı\'nın göl suyunun tapınağı kaplayacak olması', ['Bir depremin tapınağı yıkması', 'Turizm gelirlerini artırmak', 'Savaş sırasında bombalanması'], 'UNESCO Nubia Kampanyası ile tapınaklar parça parça sökülerek 60 metreden yüksek bir yere yeniden kurulmuştur.'),
  ('Nefertiti Büstü\'nü 1912\'de Amarna\'da Thutmose atölyesinde bulan Alman arkeolog kimdir?', 'Ludwig Borchardt', ['Heinrich Schliemann', 'Wilhelm Dörpfeld', 'Carl Humann'], 'Borchardt\'ın kazısında bulunan büst Berlin\'de sergilenir; Mısır geri verilmesini zaman zaman talep etmiştir.'),
  ('Tutankhamon\'un mezarının (KV62) arkeolojik açıdan eşsiz sayılmasının başlıca nedeni nedir?', 'Neredeyse sağlam ve zengin eşyalarla bulunmuş bir kral mezarı olması', ['Dünyanın en büyük piramidi olması', 'Hiçbir eser içermemesi', 'Hititlerin yaptırması'], 'Kral Vadisi\'nde çoğu kral mezarı soyulmuşken KV62 büyük ölçüde sağlam kalmış, binlerce eser vermiştir.'),
  ('"Tutankhamon\'un laneti" söylentisinin bilimsel olarak desteklenmemesinin gerekçesi hangisidir?', 'Mezarı açanların çoğunun uzun yaşaması', ['Carnarvon\'un mezardan sonra hiç hastalanmaması', 'Mezarın hiç açılmaması', 'Carter\'ın erken ölmesi'], 'Carter ve ekibinin birçoğu uzun yıllar yaşamıştır; Carnarvon\'un ölümü sivrisinek ısırığı enfeksiyonuna bağlanır.'),
  ('George Smith\'in 1872\'de British Museum\'daki tabletlerden okuyup duyurduğu metin hangi anlatıya benzerliğiyle şaşkınlık yarattı?', 'Kitab-ı Mukaddes\'teki Tufan anlatısına', ['Mısır Ölüler Kitabı\'ndaki kalp tartı sahnesine', 'Homeros\'un İlyada\'sına', 'Hint Vedalarına'], 'Smith, Gılgamış Destanı\'nın 11. tabletinde Nuh Tufanı\'na çok benzeyen bir tufan anlatısı bulmuştur.'),
  ('Babil\'i 1899-1917 arasında kazan Alman arkeolog kimdir?', 'Robert Koldewey', ['Ludwig Borchardt', 'Carl Humann', 'Ernst Herzfeld'], 'Koldewey\'in kazısı İştar Kapısı\'nı ve kentin planını ortaya çıkarmıştır. Asma Bahçeler ise arkeolojik olarak kanıtlanamamıştır.'),
  ('Uruk\'ta bulunan en eski kil tabletlerdeki işaretlerin içeriği çoğunlukla nedir?', 'Ekonomik kayıtlar ve sayımlar', ['Tapınak ilahileri ve büyü formülleri', 'Dua metinleri', 'Kral yıllıkları'], 'En eski yazı, tapınak ekonomisinde mal, hayvan ve tahıl kayıtları için doğmuştur; edebiyat sonra gelir.'),
  ('Behistun Yazıtı\'nın üç dilli olması çivi yazısının çözümünü nasıl kolaylaştırmıştır?', 'Bilinen Eski Farsçadan Elamca ve Akadca metinlere geçilebilmesini sağlamıştır', ['Metinlerin yalnızca Yunanca olması sayesinde', 'Yazıtın Latince olmasıyla', 'Yazıtın tek dilli olmasıyla'], 'Eski Farsça önce çözüldü; aynı metnin Elamca ve Akadca karşılıkları da böylece okunabildi. Bu, Rosetta Taşı\'na benzer bir mantıktır.'),
  ('Pasargadae\'deki yapı hangi hükümdara aittir?', 'Kyros (Büyük Kyros)\'un mezarı', ['Dareios\'un Persepolis\'teki büyük sarayı', 'Xerxes\'in kapısı', 'Artaxerxes\'in tapınağı'], 'Pasargadae, Kyros\'un kurduğu ilk Pers başkenti olup tek odalı basamaklı mezar yapısıyla bilinir.'),
  ('Ölü Deniz Yazmaları 1947\'de nerede bulunmuştur?', 'Kumran Mağaraları', ['Kudüs Tapınağı\'nın bodrum odaları', 'Megiddo Höyüğü', 'Petra'], 'Bir Bedevi çoban, Kumran yakınındaki mağarada testiler içinde İbranice yazmalar bulmuştur.'),
  ('Ölü Deniz Yazmaları\'nın Eski Ahit metinleri açısından önemi nedir?', 'Bilinen en eski İbranice metin nüshalarını içermesi', ['Latince Kitab-ı Mukaddes çevirisinin en eski nüshası olması', 'Mısır papirüsü olması', 'İslamî bir metin olması'], 'Yazmalar, yaklaşık iki bin yıl öncesine ait İbranice metinler içerir.'),
  ('Kathleen Kenyon\'un 1950\'lerde kazdığı Eriha (Jericho) neden önemlidir?', 'Dünyanın en eski surlu yerleşimlerinden biri ve Neolitik kuleye sahip olması', ['Roma imparatoru sarayı olması', 'İlk Türk kenti olması', 'İlk liman olması'], 'Eriha\'da Neolitik döneme ait taş sur ve kule bulunmuştur; kent, erken yerleşik yaşamın simgelerindendir.'),
  ('Bağdat Müzesi 2003\'te hangi olay sırasında yağmalanmıştır?', 'ABD öncülüğündeki Irak işgali', ['Birinci Dünya Savaşı sırasındaki Osmanlı çekilişi', 'Moğol istilası', 'Suez Krizi'], 'Nisan 2003\'te işgalin kargaşasında binlerce eser çalınmış, bir kısmı geri alınmıştır.'),
  ('Knossos\'taki fresklerde sık görülen "boğa üzerinde atlama" sahnesi Minos kültürü hakkında ne düşündürür?', 'Boğanın dinî ve törensel öneme sahip olduğunu', ['Dönemin ana ekonomisinin balıkçılığa dayandığını', 'Savaş sırasında boğaların kullanıldığını', 'Halkın tarım yapmadığını'], 'Boğa betimleri hem tören hem inanç alanında önemli bir yer tutar; efsanedeki Minotor anlatısıyla da ilişkilendirilir.'),
  ('Linear B tabletlerinin içeriğinin çoğunlukla ne olduğu anlaşılınca hangi sonuç çıkarıldı?', 'Saray ekonomisinin envanter ve erzak kayıtları olduğu', ['Destan ve şiirlerden oluştuğu', 'Kralların savaş anlatıları olduğu', 'Dinî ilahiler olduğu'], 'Tabletler çoğunlukla mal, hayvan ve işçi kayıtları içerir. Böylece Miken saray ekonomisinin yönetim düzeni ortaya çıkmıştır.'),
  ('Linear A yazısı hakkında günümüzdeki bilimsel durum hangisidir?', 'Henüz kesin olarak çözülememiştir', ['Tamamen çözülüp Yunanca olduğu kanıtlanmıştır', 'Hititçedir', 'Latinceden türemiştir'], 'Linear A, Minos dönemine ait olup dilinin ne olduğu belirlenemediği için okunamamaktadır.'),
  ('Santorini\'deki Akrotiri yerleşiminin "Bronz Çağı Pompeii\'si" olarak anılmasının nedeni nedir?', 'Volkanik külle örtülüp yapıların ve fresklerin iyi korunması', ['Bir depremde tamamen denize gömülmesi', 'Savaşta yakılıp külü savrulması', 'Çölde kumlara gömülmesi'], 'Büyük patlamadan sonra kül altında kalan Akrotiri\'de freskli çok katlı evler korunmuştur. Kazıyı Spyridon Marinatos başlatmıştır.'),
  ('Antikythera Mekanizması\'nın bilim tarihi açısından önemi nedir?', 'Astronomik olayları hesaplayan dişli düzenekli antik bir aygıt olması', ['Antik bir saat kulesi olması', 'Mısır\'dan gelen bir mumya', 'Hitit tablet kutusu olması'], '1901\'de batıktan çıkan mekanizma, güneş ve ay hareketleriyle tutulmaları hesaplayan karmaşık dişliler içerir.'),
  ('Antikythera Mekanizması\'nın bulunduğu batığı keşfeden kimlerdir?', 'Sünger dalgıçları', ['Alman arkeologlar', 'Hazine avcıları', 'Fransız denizciler'], 'Batık, 1900\'de fırtınadan sığınan sünger dalgıçlarınca bulunmuştur; mekanizma 1901\'de fark edilmiştir.'),
  ('Atina Agorası\'nda bulunan ve üzerine isim yazılan çömlek parçaları (ostrakon) hangi uygulamayı gösterir?', 'Kentten sürülecek kişiyi belirleyen oylamayı', ['Tapınak vergisinin ödenip kayda geçirilmesini', 'Spor müsabakası sonucunu', 'Kehanet isteğini'], 'Ostrakon, vatandaşların istenmeyen siyasetçiyi oylamayla sürgüne göndermesi için kullanılan oy puludur.'),
  ('Pompeii\'de Giuseppe Fiorelli\'nin uyguladığı yöntem neydi?', 'Küllerdeki boşluklara alçı dökerek insan ve hayvan kalıpları elde etmek', ['Küllerin tamamını bir kerede kaldırmak', 'Kentin tümünü yeniden inşa etmek', 'Evleri toprakla örtmek'], 'Fiorelli\'nin yöntemiyle kül içindeki boşluklara alçı doldurulup ölenlerin son anları kalıplanmıştır.'),
  ('Roma\'nın Kolezyum\'unun (Flavius Amfitiyatrosu) açılışı hangi imparator döneminde yapılmıştır?', 'Titus', ['Augustus', 'Konstantin', 'Justinianus'], 'Yapı Vespasianus tarafından başlatılmış, MS 80\'de oğlu Titus tarafından açılmıştır.'),
  ('Stonehenge\'in yönlenişi hangi gözlemle ilişkilendirilir?', 'Yaz gündönümü gündoğumu ve kış gündönümü gün batımı', ['Ekinoks gecesindeki yıldız doğuşu ve Venüs\'ün gökyüzü hareketi', 'Tutulma takvimi', 'Kuzey yıldızı hizası'], 'Anıtın ana ekseni yaz gündönümü gündoğumuna doğru uzanır; bu da takvim ve inanç işlevini düşündürür.'),
  ('İrlanda\'daki Newgrange\'in en belirgin özelliği nedir?', 'Kış gündönümünde gün ışığının uzun koridordan içeri girmesi', ['Büyük bir tiyatro olması', 'Piramit biçiminde olması', 'Altın heykellerle dolu olması'], 'Newgrange, yaklaşık MÖ 3200\'e ait mezar odasıdır ve Mısır piramitlerinden eskidir; kış gündönümü sabahı ışık odaya girer.'),
  ('İskoçya\'daki Skara Brae köyü, hangi çağın yaşam koşullarını gösterir?', 'Neolitik taş evlerin ve taş mobilyanın korunduğu bir köy', ['Roma garnizon yaşamını', 'Viking ticaret limanını', 'Orta Çağ manastırını'], 'Fırtınayla kumdan çıkan köyde taştan yatak, dolap ve ocaklar korunmuştur.'),
  ('Ötzi\'nin yanında bakır bir baltanın bulunması hangi dönemin göstergesidir?', 'Bakır (Kalkolitik) Çağı', ['Paleolitik (Eski Taş Çağı) sonu', 'Demir Çağı', 'Orta Çağ'], 'Bakır balta, MÖ 4. binyılın sonlarındaki Bakır Çağı\'na işaret eder.'),
  ('Almanya\'daki Neander Vadisi\'nde 1856\'da bulunan kalıntılar hangi insan türünü tanıtmıştır?', 'Neandertal', ['Cro-Magnon', 'Homo erectus', 'Australopithecus'], 'Düsseldorf yakınındaki Feldhofer Mağarası\'nda bulunan kemikler, Neandertallerin bilime tanıtılması olmuştur.'),
  ('Laetoli\'de (Tanzanya) Mary Leakey\'nin 1978\'de bulduğu ayak izleri neyi kanıtlar?', 'İki ayak üzerinde yürümenin yaklaşık 3,6 milyon yıl önce var olduğunu', ['İnsanın ateşi kullandığını', 'İlk sürüş aracının varlığını', 'Tarımın başlangıcını'], 'Volkanik külde korunan izler, ilk atalarımızın dik yürüdüğünü gösterir.'),
  ('Lascaux Mağarası\'nın 1963\'te halka kapatılmasının nedeni nedir?', 'Ziyaretçilerin soluduğu karbondioksit ve nemin resimlere zarar vermesi', ['Bir depremin mağarayı yıkması', 'Hükümetin yasaklaması', 'Arkeolojik kazı bitmesi'], 'Ziyaretçi sayısı resimlerde küf ve solmaya yol açtığından, kopya mağara (Lascaux II) yapılmıştır.'),
  ('Chauvet Mağarası resimlerinin yaklaşık 36.000 yıllık olması hangi sonucu doğurur?', 'Sanatın Üst Paleolitik\'in erken döneminde zaten ileri düzeyde olduğunu', ['Sanatın Orta Çağ\'da başladığını', 'Resimlerin sahte olduğunu', 'Mağaranın Roma\'dan kaldığını'], 'Chauvet\'in gelişmiş çizimleri, sanatsal ifadenin çok eskiye uzandığını gösterir.'),
  ('Mağara resimlerinde kırmızı ve sarı renklerin elde edilmesinde hangi madde kullanılmıştır?', 'Demir oksit içeren toprak boyalar', ['Bitki özleri ve meyve sularından yapılan boya', 'Sentetik boya', 'Çamur ve kan karışımı'], 'Kırmızı ve sarı tonlar için demir oksitli toprak, siyah için kömür ve manganez kullanılmıştır.'),
  ('Terakota askerlerinin açığa çıkmasından kısa süre sonra boyalarının solması, arkeolojide hangi sorunu gösterir?', 'Organik boyaların havayla temasta bozulması ve koruma zorluğu', ['Boyaların aslında hiç bulunmaması', 'Boyaların zehirli olması', 'Askerlerin sonradan boyanması'], 'Heykeller aslen canlı renklerle boyalıydı; havayla temas edince boya tabakası hızla bozulmuş, koruma teknikleri geliştirilmiştir.'),
  ('Anyang\'da bulunan Shang dönemi kemik yazıtlarının (kehanet kemikleri) önemi nedir?', 'Bilinen en eski Çin yazısı örneklerini içermeleri', ['Sanskrit metinleri taşımaları', 'Roma tarihini anlatmaları', 'Moğol fermanı olmaları'], 'Kaplumbağa kabukları ve hayvan kemikleri üzerindeki kehanet yazıları, Çin yazısının MÖ 2. binyıldaki biçimini gösterir.'),
  ('Hindistan Alt Kıtası\'nda Harappa\'yı 1921\'de kazmaya başlayan ve Mohenjo-daro\'nun kazısıyla birlikte İndus Uygarlığı\'nı tanıtan çalışmalar hangi sonucu doğurmuştur?', 'Mısır ve Mezopotamya ile çağdaş büyük bir şehir uygarlığının ortaya çıkması', ['Roma\'nın ilk kolonisinin bulunması', 'Hitit\'in doğu sınırının belirlenmesi', 'Pers\'in başkentinin bulunması'], 'Kazılar planlı kentleri, kanalizasyon ve mühür kültürüyle İndus Vadisi uygarlığını bilim dünyasına tanıtmıştır.'),
  ('Mohenjo-daro\'da bulunan "Büyük Hamam" kentin hangi yönünü gösterir?', 'Su yapıları ve kamusal yapılara önem verildiğini', ['Savaş stratejisini', 'Dinî yazıtların bolluğunu', 'Krallar listesini'], 'Büyük Hamam, kamusal bir su yapısıdır ve kentin mühendislik düzeyini gösterir.'),
  ('İndus mühürlerindeki yazı bugün hâlâ hangi durumdadır?', 'Çözülememiştir', ['Tamamen çözülmüştür', 'Sanskrit olduğu kanıtlanmıştır', 'Latince olduğu kanıtlanmıştır'], 'İndus yazısı kısa ve çok az metin içerdiğinden kesin çözüm yapılamamıştır.'),
  ('Angkor çevresinde LiDAR (lazer tarama) kullanılmasının arkeolojiye sağladığı en önemli yarar nedir?', 'Ormanın altındaki yapı ve su ağlarını kazı yapmadan görünür kılması', ['Yapıların yaşını doğrudan vermesi', 'Yazıtları okuması', 'Eserleri temizlemesi'], 'LiDAR, bitki örtüsü altındaki yer şekillerini haritalar; böylece Angkor\'un geniş kentsel dokusu ortaya çıkarılmıştır.'),
  ('Hiram Bingham\'ın 1911\'de Machu Picchu\'yu dünyaya tanıtan keşfinde yerel çiftçilerin rolü nedir?', 'Bölgeyi bilen yerel halkın onu alana yönlendirmesi', ['Çiftçilerin alanı hiç bilmemesi', 'Çiftçilerin kazıyı yönetmesi', 'Çiftçilerin alanı yıkması'], 'Alan yerel halkça biliniyordu; Bingham, yerel bir çocuk rehber sayesinde bölgeye ulaşmıştır. Bu yüzden "keşif" kavramı tartışılır.'),
  ('Machu Picchu hangi uygarlığa aittir ve kime atfedilen bir kral konutu olarak yorumlanır?', 'İnka; Pachacuti\'ye', ['Maya; Pakal\'a', 'Aztek; Montezuma\'ya', 'Olmek; La Venta Kralı\'na'], 'Machu Picchu, 15. yüzyıl İnka yönetiminde kurulmuş bir yerleşimdir ve Pachacuti\'nin kraliyet çiftliği olarak yorumlanır.'),
  ('Palenque\'de 1952\'de Alberto Ruz Lhuillier\'in Yazıtlar Tapınağı\'nın altında bulduğu mezar kime aittir?', 'Pakal', ['Montezuma', 'Atahualpa', 'Pachacuti'], 'Tapınağın altındaki mezar, Maya kralı Pakal\'a aittir; jade maskesiyle ünlüdür.'),
  ('Chichen Itza\'daki El Castillo\'da ekinoks günlerinde ortaya çıkan ışık-gölge etkisi neyi gösterir?', 'Maya mimarisinin astronomik bilgiyle uyumlu tasarlanması', ['Yapının Roma yapımı olması', 'Yapının yeraltı olması', 'Yapının denizden çıkması'], 'Ekinokslarda merdivenlerde yılan gibi görünen gölge, Maya\'nın takvim ve astronomi bilgisini yansıtır.'),
  ('Aksum Krallığı\'nın en bilinen anıtları olan dikilitaşlar (stel) nerede bulunur?', 'Etiyopya', ['Mısır', 'Libya', 'Sudan'], 'Aksum, Etiyopya\'nın kuzeyinde yer alan eski bir krallık başkentidir ve dikilitaşlarıyla tanınır.'),
  ('Etiyopya\'daki Lalibela\'nın en bilinen özelliği nedir?', 'Tek parça kayaya oyulmuş kiliseler', ['Piramit biçimli mezarlar ve basamaklı tapınaklar', 'Sütunlu tapınaklar', 'Yer altı şehri'], 'Lalibela, 12-13. yüzyıllarda tek parça kayaya oyulan kiliselerle tanınır.'),
  ('Benin Bronzları 1897\'de nasıl dünya müzelerine dağılmıştır?', 'İngiliz cezalandırma seferi sırasında yağmalanarak', ['Alman misyonerlerin satın almasıyla', 'Mısır\'dan hediye edilerek', 'Müzelerin kazıları sonucu'], '1897\'de İngiliz birlikleri Benin Krallığı\'nı işgal etmiş, saraydaki bronz ve fildişi eserler Avrupa\'ya taşınmıştır; iade tartışmaları sürmektedir.'),
  ('Uluburun Batığı\'ndaki yükte tonlarca bakır ve kalay külçesinin bulunması neyi gösterir?', 'Tunç üretimi için gerekli hammaddelerin Doğu Akdeniz\'de uzun mesafe ticaretini', ['Gemide demir silah bulunduğunu', 'Gemi sahiplerinin Romalı olduğunu', 'Yükün yalnız yiyecek taşıdığını'], 'Bakır ve kalay, tunç yapmak için gerekli iki metaldir; gemi, Geç Tunç Çağı\'nın uluslararası ticaretini belgelemektedir.'),
  ('İsveç\'te Vasa savaş gemisinin 1628\'deki ilk seferinde batmasının başlıca teknik nedeni nedir?', 'Ağır silah yükü nedeniyle gemi dengesinin yetersiz olması', ['Düşman topçusu', 'Buz kütlesine çarpması', 'Yıldırım düşmesi'], 'Vasa, dar gövdesi ve ağır top güvertesi yüzünden kararsız olup birkaç yüz metre sonra batmıştır; 1961\'de çıkarılmıştır.'),
  ('Mary Rose\'un 1982\'de çıkarılmasının önemi nedir?', '16. yüzyıl Tudor gemi yaşamına dair çok iyi korunmuş bir "zaman kapsülü" olması', ['Roma savaş gemisi olması', 'Viking gemisi olması', 'Antik Mısır teknesi olması'], '1545\'te Solent\'te batan İngiliz savaş gemisinden silahlar ve günlük eşya çıkmıştır.'),
  ('Karbon-14 yönteminin ölçtüğü şey aşağıdakilerden hangisidir?', 'Organik maddede kalan radyoaktif karbonun oranı', ['Seramikteki demir oksit oranı', 'Taşın sertliği', 'Metallerdeki kalay miktarı'], 'Canlı öldükten sonra C-14 düzenli azalır; kalan oran, ölümden bu yana geçen süreyi verir.'),
  ('Radyokarbon yönteminin yarı ömrü yaklaşık 5730 yıldır. Bir kemik örneğinde başlangıçtaki karbon-14 miktarının sekizde biri kalmışsa örnek yaklaşık kaç yaşındadır?', '17.190 yıl', ['11.460 yıl', '22.920', '34.380'], 'Sekizde bir, üç yarı ömre karşılık gelir (1/2 x 1/2 x 1/2). 3 x 5730 = 17.190 yıl eder.'),
  ('Ağaç halkalarına dayanan tarihleme yöntemine ne ad verilir?', 'Dendrokronoloji', ['Termolüminesans', 'Seriation', 'Palinoloji'], 'Dendrokronoloji, ağaç halkası genişliklerinin yıllar arası kalıbını karşılaştırarak yıl yıl kesin tarih verir ve radyokarbonu kalibre eder.'),
  ('Polen (çiçek tozu) analizinin arkeolojiye katkısı nedir?', 'Geçmiş bitki örtüsü ve iklim değişimlerini yeniden kurmak', ['Metal türünü belirlemek', 'Yazıyı çözmek', 'Taş aletin ustasını bulmak'], 'Çökellerde korunan polenler, geçmişin bitki örtüsünü ve tarımın yayılışını gösterir.'),
  ('Yer radarı ve manyetometre gibi yöntemlerin kazıdan önce kullanılmasının nedeni nedir?', 'Toprağı bozmadan gömülü yapıları saptamak', ['Seramik pişirip yeni kaplar üretmek için hazırlık yapmak', 'Tarih belirlemek', 'Yazıyı çözmek'], 'Jeofizik yöntemler, toprak altındaki duvar ve yapıların izlerini zarar vermeden gösterir.'),
  ('Yüzey araştırması (survey) ile kazı arasındaki temel fark nedir?', 'Yüzey araştırması toprağı kazmadan yüzeydeki buluntuları kaydeder', ['Yüzey araştırması her zaman daha pahalıdır', 'Kazı yapılmadan hiçbir buluntu çıkmaz', 'İkisi aynı yöntemdir'], 'Yüzey araştırması geniş alanlarda yerleşme dağılımını kazı yapmadan belirler; kazı ise tabaka tabaka toprağı açarak ayrıntı verir.'),
  ('Eski bir yerleşimde bulunan arpa ve buğday tohumlarının incelenmesini ve yöntem olarak su ile ayırma (flotasyon) kullanılmasını hangi alan kapsar?', 'Arkeobotani', ['Epigrafi', 'Numismatik', 'Heykeltıraşlık'], 'Arkeobotani, bitki kalıntılarından beslenme ve tarım bilgisi çıkarır; flotasyon tohumları topraktan ayırır.'),
  ('Milo Venüsü 1820\'de hangi adada bulunmuştur?', 'Milos (Melos)', ['Rodos (Helios Heykeli\'nin adası)', 'Girit', 'Sicilya'], 'Ege\'deki Milos adasında bir köylü tarafından bulunan heykel, Fransa\'ya götürülmüş ve Louvre\'da sergilenmiştir.'),
  ('Christian Jürgensen Thomsen\'in 1830\'larda ortaya koyduğu sınıflandırma hangisidir?', 'Üç Çağ Sistemi (Taş-Tunç-Demir)', ['Dört Mevsim Sistemi (tarım takvimine dayalı)', 'Beş Kıta Sistemi', 'İki Dönem Sistemi'], 'Thomsen, Kopenhag müzesindeki eserleri aletlerin yapıldığı malzemeye göre taş, tunç ve demir çağlarına ayırmıştır.'),
  ('V. Gordon Childe\'ın 1936\'da kullanıma soktuğu "Neolitik Devrim" kavramı neyi anlatır?', 'Avcı-toplayıcılıktan tarıma ve yerleşik yaşama geçişi', ['Metal işlemeye başlanmasını', 'Yazının icadını', 'Tekerleğin buluşunu'], 'Childe, tarımın başlangıcını insanlığın en köklü dönüşümlerinden biri olarak tanımlamıştır.'),
  ('Max Mallowan\'ın eşi olarak kazılara katılan ünlü İngiliz yazar kimdir?', 'Agatha Christie', ['Virginia Woolf', 'Daphne du Maurier', 'Jane Austen'], 'Agatha Christie, Mallowan\'ın Nimrud ve Tell Brak gibi alanlardaki kazılarında bulunmuş, bazı romanlarına arkeolojik ortam yansımıştır.'),
  ('Piltdown Adamı\'nın sahte olduğu hangi yöntemle ortaya çıkarılmıştır?', 'Kemiklerin florür testi ve incelenmesiyle', ['Radyokarbon ve DNA analiziyle 1912\'de', 'Mısır yazıtıyla', 'Bir tabletin okunmasıyla'], '1953\'te yapılan testler çenenin bir orangutana, kafatasının modern insana ait olduğunu ve kemiklerin boyandığını göstermiştir.'),
  ('Kanada\'daki L\'Anse aux Meadows\'un önemi nedir?', 'Avrupalıların (Vikinglerin) Kolomb\'dan yaklaşık 500 yıl önce Amerika\'ya ulaştığını kanıtlaması', ['Roma\'nın Amerika\'ya gittiğini göstermesi', 'İlk Çin yerleşimi olması', 'İlk İspanyol kolonisi olması'], 'Newfoundland\'daki alan, yaklaşık MS 1000\'e ait Viking yapı kalıntıları vermiş, Helge Ingstad tarafından 1960\'ta bulunmuştur.'),
  ('2012\'de Leicester\'da bir otopark altında bulunan iskeletin kimliği hangi kralla eşleşmiştir?', 'III. Richard', ['VIII. Henry', 'I. Elizabeth', 'Aslan Yürekli Richard'], 'Omurga eğriliği ve DNA incelemesi, iskeletin Bosworth\'ta ölen III. Richard\'a ait olduğunu göstermiştir.'),
  ('Antik tiyatrolarda seyircilerin oturduğu basamaklı bölüme ne ad verilir?', 'Cavea', ['Orkestra', 'Skene', 'Parodos'], 'Cavea, tiyatronun oturma kısmıdır. Orkestra koronun, skene ise sahne binasının yeridir.'),
  ('Yunan mimarisinde başlığı iki yanda büyük sarmal (volüt) kıvrımlarıyla tanınan sütun düzeni hangisidir?', 'İon', ['Dor', 'Korint', 'Toskan'], 'İon başlığı iki yanda sarmal kıvrımlar taşır. Dor sade, Korint ise akant yapraklıdır.'),
  ('Mısır\'da eski krallık dönemi soyluları için yapılan düz çatılı, eğik yan duvarlı mezar tipi hangisidir?', 'Mastaba', ['Tholos', 'Tümülüs', 'Lahit'], 'Mastaba, dikdörtgen planlı, düz çatılı mezar yapısıdır; basamaklı piramit mastabaların üst üste yığılmasından gelişmiştir.'),
  ('Anadolu\'da toprak yığınıyla örtülen gömüt tipine ne denir?', 'Tümülüs', ['Mastaba', 'Piramit', 'Katakomb'], 'Tümülüs, mezarın üstüne toprak ve taş yığılarak yapılan yapay tepedir; Gordion ve Bin Tepe\'de örnekleri vardır.'),
  ('Kapadokya\'da peribacalarının oluşumunu en iyi hangisi açıklar?', 'Yumuşak volkanik tüfün erozyonla aşınırken sert bir taşın tepede kalması', ['Depremle taşların devrilmesi', 'Kum fırtınasında oluşan rüzgâr heykelleri', 'İnsanların bilinçli olarak yontup bırakması'], 'Erciyes ve Hasandağı püskürmelerinden oluşan yumuşak tüf, sert bazalt başlıkları koruyarak sütunlar hâlinde aşınmıştır; sonradan insanlar bunları oymuştur.'),
  ('Kapadokya\'daki yeraltı şehirlerinin (Derinkuyu, Kaymaklı) özelliğini en iyi hangisi belirtir?', 'Yuvarlak taş kapılar, havalandırma bacaları ve depolama alanlarıyla savunma amaçlı yaşam alanları', ['Mısır tarzı mezar odaları', 'Roma amfitiyatrosu', 'Sadece tapınak yapısı'], 'Yeraltı şehirleri, tehlike dönemlerinde sığınılan çok katlı yerleşimlerdir; kapıları içeriden yuvarlanan taşlarla kapatılırdı.'),
  ('Göreme Açık Hava Müzesi\'ndeki kaya kiliselerinin duvar resimleri hangi dönemin sanatını yansıtır?', 'Bizans', ['Hitit', 'Roma Cumhuriyeti', 'Selçuklu'], 'Göreme\'deki kaya kiliseleri Bizans sanatının duvar resimleriyle bezelidir; Karanlık Kilise en iyi korunmuş örneklerdendir.'),
  ('Aksaray\'daki Ihlara Vadisi\'nin tarih açısından önemi nedir?', 'Kayalara oyulmuş çok sayıda Bizans kilisesi barındırması', ['Hitit başkenti olması', 'Roma tiyatrosu bulunması', 'Pers sarayı olması'], 'Melendiz Çayı boyunca uzanan vadide yamaçlara oyulmuş çok sayıda Bizans kilisesi bulunur.'),
  ('Yerebatan Sarnıcı\'nı 6. yüzyılda yaptıran Bizans imparatoru kimdir?', 'I. Justinianus', ['I. Konstantinos', 'Herakleios', 'II. Mehmed'], 'Justinianus, Nika İsyanı\'ndan sonra Ayasofya ile birlikte büyük sarnıcı da yaptırmıştır. Sarnıçta çok sayıda devşirme sütun kullanılmıştır.'),
  ('Yerebatan Sarnıcı\'ndaki devşirme sütunların varlığı neye işaret eder?', 'Daha eski yapılardan alınan malzemenin yeniden kullanıldığına', ['Sütunların yalnızca Osmanlı döneminde yapıldığına', 'Sarnıcın Mısır\'da yapıldığına', 'Sütunların sahte olduğuna'], 'Sütunlar ve Medusa başı gibi bloklar eski yapılardan getirilmiştir; bu "spolia" uygulamasıdır.'),
  ('Denizli\'deki Hierapolis\'te bulunan Plutonion\'un özelliği nedir?', 'Zehirli gaz çıkışı nedeniyle "Cehennem Kapısı" olarak bilinmesi', ['Zeus Tapınağı olması', 'Kaya mezarı olması', 'Kütüphane olması'], 'Plutonion, mağara ağzından çıkan karbondioksit gazının hayvanları öldürmesiyle ünlüdür ve ölüler dünyası inancıyla ilişkilendirilmiştir.'),
  ('Hierapolis\'in ünlü Ölüler Şehri (Nekropol) nasıl bir özellik gösterir?', 'Çok sayıda tümülüs, lahit ve mezar tipini bir arada barındırması', ['Yalnızca tek bir lahit içermesi', 'Sadece Hitit mezarları barındırması', 'Hiç mezar bulundurmaması'], 'Hierapolis nekropolü, Anadolu\'nun en geniş ve çeşitli mezar topluluklarından biridir.'),
  ('Kütahya\'daki Aizanoi antik kentinin en tanınmış yapısı hangisidir?', 'Zeus Tapınağı', ['Mausoleion', 'Artemis Tapınağı', 'Celsus Kütüphanesi'], 'Aizanoi Zeus Tapınağı, Anadolu\'daki en iyi korunmuş Roma dönemi tapınaklarından biridir; kentte ayrıca iç içe stadyum-tiyatro vardır.'),
  ('Antalya\'daki Hadrian Kapısı (Üçkapılar) neden yapılmıştır?', 'İmparator Hadrianus\'un kente ziyaretini anmak için', ['Pers kralına karşı kazanılan büyük deniz zaferini anmak için', 'Bizans savunması için', 'Selçuklu sultanı için'], 'Üç kemerli mermer kapı, MS 130\'da imparatorun Antalya (Attaleia) ziyareti onuruna yapılmıştır.'),
  ('İznik Gölü\'nde 2014\'te hava fotoğraflarıyla fark edilen su altı yapısı nasıl yorumlanmıştır?', 'Bir kilise (bazilika) kalıntısı olarak', ['Hitit tapınağı ve su kaynağı olarak', 'Roma limanı olarak', 'Selçuklu sarayı olarak'], 'İznik Gölü\'ne batmış kilise yapısı, bölgenin erken Hristiyanlık dönemiyle ilişkilendirilmiştir.'),
  ('Bir höyüğün (tell) yüzyıllar boyunca yükselmesinin başlıca nedeni nedir?', 'Yıkılan kerpiç yapıların üstüne yenilerinin aynı yerde inşa edilmesi', ['Rüzgârın kum taşıması', 'Nehrin yatak değiştirmesi', 'Taş ocaklarından getirilen malzeme'], 'Kerpiç evler çöktüğünde enkaz düzlenip üstüne yeniden yapı yapılır; bu döngü höyüğü yükseltir ve tabakalar oluşturur.'),
  ('Bir buluntunun bulunduğu yerin, tabakanın ve diğer eşyalarla ilişkisinin kaydedilmesinin amacı nedir?', 'Eserin bağlamını koruyarak yorum ve tarihleme yapılabilmesi', ['Müzede güzel görünmesi', 'Sigorta bedelini artırmak', 'Kazı süresini kısaltmak'], 'Bağlam bilgisi (konum, tabaka, eşlik eden buluntular) yoksa eser yalnızca güzel bir nesne olarak kalır ve tarihsel değeri azalır.'),
  ('İskenderiye Feneri\'nin yok olmasında en önemli etken nedir?', '14. yüzyıldaki depremler', ['Büyük İskender\'in yıktırması', 'Yangında yanması', 'Savaşta Romalıların yıkması'], 'Fener, yüzyıllar içinde depremlerle zarar görmüş; kalıntılar daha sonra bir Memlûk kalesinin yapımında kullanılmıştır.'),
  ('Efes\'teki Artemis Tapınağı\'nın MÖ 356\'da yakılmasının sorumlusu olarak anlatılan kişi hangi amacı taşıyordu?', 'Adını ölümsüzleştirmek', ['Rüşvet almak', 'Roma\'ya karşı ayaklanmak', 'Hazine çalmak'], 'Herostratos\'un ünlenmek için tapınağı yaktığı anlatılır; bu yüzden adı "ün için yıkım" anlamında kullanılır.'),
  ('Roma\'nın Troya\'ya (Ilium) özel ilgi göstermesinin ideolojik nedeni nedir?', 'Romalıların kendilerini Truva kökenli Aeneas\'ın soyundan saymaları', ['Troya\'nın Roma\'ya komşu olması', 'Altın yatakları', 'Mısır ticareti'], 'Roma efsanesinde kuruluş, Truva\'dan kaçan Aeneas\'a dayandırıldığından Julius Caesar ve Augustus gibi yöneticiler Ilion\'u desteklemiştir.'),
  ('Nemrut Dağı\'ndaki heykel başlarının gövdelerinden ayrı yerde bulunması hangi nedenle açıklanır?', 'Depremler ve erozyonla yıkılmaları', ['Heykellerin başsız olarak yapılmış olmasıyla', 'Heykellerin Roma\'ya götürülmesi', 'Heykellerin tamamen yok edilmesi'], 'Antik heykeller zamanla deprem ve aşınmayla devrilmiş, başları terasta yere düşmüştür.'),
  ('Anadolu\'daki Roma yollarında uzaklığı gösteren dikili taşlar için kullanılan terim hangisidir?', 'Mil taşı (milion)', ['Stel (yazıtlı dikili taş)', 'Obelisk', 'Menhir'], 'Roma yollarında belli aralıklarla konulan mil taşları, imparator adı ve mesafeyi taşıyarak yol ağını ve tarihini aydınlatır.'),
  ('Göbeklitepe\'nin Şanlıurfa kenti çevresinde bulunması, Verimli Hilal\'de hangi sürecin merkezi olduğunu düşündürür?', 'Tarımın ve yerleşik hayatın ilk ortaya çıktığı bölgenin merkezi', ['Deniz ticaretinin merkezi', 'Madencilik merkezi', 'Kervan yollarının batı ucu'], 'Şanlıurfa çevresi, Verimli Hilal\'in kuzey kolunda yer alır; evcilleştirme ve yerleşiklik buradaki yerleşimlerde izlenir.'),
  ('Eski Mısır mumyalamasında vücudu kurutmak için kullanılan temel madde nedir?', 'Natron tuzu', ['Bal ve sirke karışımı', 'Zeytinyağı ve kil', 'Taze palmiye suyu ve kireç'], 'Natron, doğal bir tuz karışımıdır ve vücuttaki suyu çekerek kurumasını sağlar; işlem yaklaşık 70 gün sürerdi.'),
  ('Mısır mumyalamasında organların konulduğu dört kaba ne ad verilir?', 'Kanopik kavanoz', ['Amfora', 'Pithos', 'Lekythos'], 'Mide, ciğer, akciğer ve bağırsaklar ayrı kavanozlarda saklanır; kanopik kavanozların kapakları dört Horus oğlunu temsil eder.'),
  ('Ölüler Kitabı\'ndaki tartı sahnesinde ölünün kalbi neyle tartılır?', 'Maat\'ın tüyüyle', ['Altın bir ağırlıkla', 'Nil suyunun taşıdığı bir taşla', 'Osiris\'in tacıyla'], 'Kalbin doğruluk tanrıçası Maat\'ın tüyünden hafif çıkması, ölünün ahirette kabul edildiğini gösterir.'),
  ('Hatşepsut\'un Deir el-Bahri tapınağındaki kabartmalarında anlatılan seferin hedefi neresidir?', 'Punt Ülkesi', ['Roma', 'Babil', 'Girit'], 'Kabartmalar, Hatşepsut\'un Punt\'a gönderdiği ticaret seferini ve getirilen buhur ağaçlarını anlatır.'),
  ('Asur saraylarının girişinde bulunan insan başlı, kanatlı boğa ya da aslan heykellerine ne denir?', 'Lamassu', ['Sfenks', 'Gryphon', 'Minotor'], 'Lamassu, sarayı kötülüklerden koruduğuna inanılan Asur figürleridir; Hursabad ve Nimrud\'dan British Museum ve Louvre\'a taşınmıştır.'),
  ('Babil\'deki Etemenanki Zigurat\'ının temel kalıntısı hangi efsaneyle ilişkilendirilir?', 'Babil Kulesi', ['Nuh\'un Gemisi', 'Truva Atı', 'Minotor Labirenti'], 'Koldewey\'in saptadığı Etemenanki tabanı, Babil Kulesi anlatısının tarihsel esini olarak yorumlanır.'),
  ('Persepolis\'in Apadana merdivenlerindeki kabartmalarda çeşitli ülke heyetlerinin hediyelerle ilerlemesi neyi simgeler?', 'Pers İmparatorluğu\'nun çok uluslu yapısını ve haraç ilişkilerini', ['Savaş esirlerinin kâbusunu', 'Yalnızca festival yürüyüşünü', 'Pers ordusunun yenilgisini'], 'Kabartmalarda farklı kıyafetli heyetler, imparatorluğun geniş bir coğrafyadan oluştuğunu ve kral karşısında sunu getirdiklerini gösterir.'),
  ('Sümer kenti Ur\'daki zigguratın kurucusu hangi hükümdardır?', 'Ur-Nammu', ['Gudea', 'Sargon', 'Asurbanipal'], 'Ur\'un Ay tanrısı Nanna\'ya adanan zigurat, III. Ur Hanedanı kralı Ur-Nammu\'nun eseridir.'),
  ('Hattuşa Yazılıkaya\'daki kabartmalarda 12 tanrının yan yana yürümesi ne anlama gelir?', 'Hitit panteonunun resmî düzeninin tasviri', ['Bir savaş yürüyüşünün zafer anısı olarak yapılması', 'Pers hükümdarına haraç yürüyüşü', 'Roma ordusu geçidi'], 'Kaya kabartmasında erkek ve kadın tanrılar alay hâlinde gösterilir; Hurri etkisindeki Hitit panteonunu yansıtır.'),
  ('Hititlerin çok sayıda yerel ve yabancı tanrıyı resmî dinlerine katmaları arkeolojik açıdan hangi buluntu grubuyla desteklenir?', 'Farklı dillerdeki dua ve ritüel tabletleriyle', ['Roma tapınaklarındaki Latince adak yazıtlarıyla', 'Yalnızca Mısır papirüsüyle', 'Hristiyan kiliseleriyle'], 'Arşivdeki Hattice, Hurrice ve Luvice ritüel metinleri, çok kültürlü bir dinî yapıyı belgeler.'),
  ('Pergamon Tiyatrosu\'nun ünlü özelliği nedir?', 'Çok dik bir yamaca kurulmuş olması', ['Yer altında kurulu gizli bir tiyatro olması', 'Denizin içinde olması', 'Hiç koltuk içermemesi'], 'Pergamon Tiyatrosu Akropol yamacına oldukça dik açıyla yerleştirilmiş olup antik dünyanın en dik tiyatrolarındandır.'),
  ('Efes Müzesi\'nde sergilenen ve çok sayıda "meme" benzeri nesneyle betimlenen Efes Artemis\'i neyi simgelemektedir?', 'Bereket ve doğurganlık', ['Savaş ve zafer', 'Denizcilik', 'Yazı ve bilgelik'], 'Efes Artemisi, Yunan Artemis\'ten farklı olarak Anadolu ana tanrıça geleneğini yansıtan bereket simgesidir.'),
  ('Milet Tiyatrosu ve Aslan Limanı\'nın birlikte anılması Milet hakkında neyi gösterir?', 'Önemli bir liman ve kültür kenti olduğunu', ['Kentin dağlık ve ulaşımı zor bir köy olduğunu', 'Kentin yok olduğunu', 'Kentin yalnızca Hitit olduğunu'], 'Milet, İon kolonizasyonunun önde gelen limanı olup tiyatrosu ve limanıyla ticari ve kültürel canlılığı gösterir.'),
  ('Zeugma adı Yunancada hangi anlama yakındır?', 'Köprü, bağ, geçit', ['Kutsal dağ, tanrıların yurdu', 'Güneş doğuşu', 'Taş ocağı'], 'Zeugma, Fırat üzerindeki geçit ve köprü noktasını belirtir; kent Seleukos Nikator tarafından kurulmuştur.'),
  ('Likya kentlerinden Arykanda hangi ilimizdedir?', 'Antalya', ['Muğla\'nın Köyceğiz ilçesi', 'Burdur\'un Bucak ilçesi', 'Denizli\'nin Acıpayam ilçesi'], 'Arykanda, Antalya\'nın Finike ilçesine bağlı dağlık bir bölgede kurulmuş teraslı bir Likya kentidir.'),
  ('Aydın Afrodisias\'taki Sebasteion hangi amaçla yapılmıştır?', 'İmparator kültü', ['Su dağıtımı', 'Gladyatör gösterisi', 'Tahıl depolama'], 'Sebasteion, Roma imparatorlarının tanrısal güçle birlikte anıldığı kabartmalı yapı olup imparator kültü merkeziydi.'),
  ('Taş Tepeler Projesi kapsamında Göbeklitepe ile birlikte anılan ve insan başı betimleriyle öne çıkan yerleşim hangisidir?', 'Karahantepe', ['Çatalhöyük\'ün kuzey höyüğü', 'Göllüdağ obsidyen atölyesi', 'Aşıklı Höyük\'ün batı yerleşimi'], 'Karahantepe, Şanlıurfa\'nın Siverek ilçesinde yer alır ve yapılarında insan figürleri öne çıkar.'),
  ('Divriği Ulu Camii ve Darüşşifası hangi yılda UNESCO\'ya girmiştir?', '1985', ['1972', '2004', '2019'], 'Divriği, Türkiye\'nin ilk UNESCO girişlerinden biridir ve İstanbul ile Göreme ile aynı yılda listeye alınmıştır.'),
  ('Aizanoi\'nin bağlı olduğu ilimiz hangisidir?', 'Kütahya', ['Eskişehir\'in Seyitgazi ilçesi', 'Afyonkarahisar\'ın Sandıklı ilçesi', 'Uşak\'ın Banaz ilçesi'], 'Aizanoi, Kütahya\'nın Çavdarhisar ilçesindedir.'),
  ('Delphi\'de "dünyanın göbeği" sayılan ve Apollon Tapınağı çevresinde bulunan taşa ne ad verilir?', 'Omphalos', ['Hristiyan haçının üç basamaklı kaidesi olan Golgota', 'Pythia\'nın oturduğu üç ayaklı bronz sehpa', 'Apollon\'un kutsal ağacının dikildiği Laurus kürsüsü'], 'Omphalos, antik Yunanlılara göre dünyanın merkezini gösteren taştır; Delphi bu yüzden kutsal merkez sayılırdı.'),
  ('Fenike alfabesinin Yunanlılara geçerken yaptığı en önemli değişiklik nedir?', 'Ünlü harflerin eklenmesi', ['Hiyeroglife dönüştürülmesi', 'Çivi biçimine sokulması', 'Sağdan sola yazımın zorunlu kılınması'], 'Fenike alfabesi yalnız ünsüzlerden oluşuyordu; Yunanlılar bazı işaretleri ünlüler için kullanarak alfabeyi geliştirdi.'),
  ('Fenikelilerin Tire kentiyle özdeşleşen ünlü ticaret malı hangisidir?', 'Mor boya', ['Zeytinyağının Phokaia\'da üretilen çeşidi', 'Mısır\'dan getirilen papirüs ruloları', 'Pergamon parşömeni'], 'Tire\'nin mor boyası, Murex deniz salyangozundan elde edilir ve çok değerliydi; Fenike adı da kızıl-mor rengi anımsatır.'),
  ('Genetik çalışmalar, Avrupa\'daki ilk çiftçilerin atalarının hangi bölgeden göç ettiğini göstermiştir?', 'Anadolu', ['Çin\'in Sarı Nehir havzası', 'Meksika yaylaları', 'Sibirya tundraları'], 'Neolitik Avrupalı çiftçilerin genomları Anadolu çiftçilerine yakındır; tarım fikirlerle birlikte insan göçüyle de yayılmıştır.'),
  ('Olmek devasa taş başlarının yapıldığı kaya türü nedir?', 'Bazalt', ['Mermer', 'Kireçtaşı', 'Kumtaşı'], 'Olmek başları volkanik bazalttan yontulmuş olup La Venta ve San Lorenzo gibi merkezlerde bulunur.'),
  ('Pont du Gard su kemeri (Fransa) hangi uygarlığın mühendislik eseridir?', 'Roma', ['Hitit', 'Pers', 'Fenike'], 'Pont du Gard, Nîmes kentine su taşıyan Roma kanalının üç sıra kemerli köprü kısmıdır.'),
  ('Roma\'nın limanı Ostia\'daki çok katlı konut yapılarına ne ad verilir?', 'İnsula', ['Domus ya da lüks özel konak', 'Villa rustica, yani çiftlik evi', 'Tabernae, sıralı küçük dükkânlar'], 'Ostia\'da yoğun nüfusun yaşadığı çok katlı apartmanlara insula denir; Roma kentleşmesinin tipik konut biçimidir.'),
  ('Çatalhöyük gibi yerleşimlerde bulunan, tarımla evcilleştirilen ilk hayvanlardan hangisi Anadolu\'da erken evcilleştirilmiştir?', 'Koyun ve keçi', ['Fil', 'At', 'Deve'], 'Güneydoğu ve Orta Anadolu\'daki Neolitik yerleşimlerde koyun ve keçi kemikleri evcilleştirmenin erken kanıtlarıdır.'),
  ('Nil kıyısındaki Hierakonpolis\'ten çıkan Narmer Paleti hangi olayı simgeler?', 'Yukarı ve Aşağı Mısır\'ın birleşmesi', ['Hititlerle yapılan barış antlaşmasının', 'Nubia seferini', 'İskender\'in gelişini'], 'Palet, Narmer\'in iki ülkenin tacıyla gösterilmesiyle Mısır\'ın birleştirilmesi geleneğini yansıtır.'),
  ('Eski Mısır\'da "Kral Vadisi" olarak anılan nekropol hangi kentin karşı yakasındadır?', 'Teb', ['Mısır\'ın kuzeyindeki Memfis kenti', 'Delta\'daki Tanis', 'İskenderiye'], 'Kral Vadisi, Yeni Krallık firavunlarının Teb\'in karşı yakasında kayalıklara oyulmuş mezarlarını barındırır.'),
  ('Kral Vadisi\'nde mezarların kayalara gizlice oyulması hangi amaçla açıklanır?', 'Mezar soygunlarını önlemek', ['Güneşi engellemek ve serinlik sağlamak', 'Nil taşkınından korunmak', 'Savaş sığınağı yapmak'], 'Piramitler soyulduğundan, Yeni Krallık firavunları mezarlarını gizli vadide yapmışlardır; yine de çoğu soyulmuştur.'),
  ('Akhenaton\'un getirdiği dinî yenilik hangi tanrıya odaklanmıştır?', 'Aten (güneş kursu)', ['Osiris (ölüler dünyasının tanrısı)', 'Anubis', 'Bastet'], 'Akhenaton, güneş kursu Aten\'i öne çıkaran tek tanrıcı eğilimli bir inanç getirmiş ve başkenti Amarna\'ya taşımıştır.'),
  ('Mısır hiyerogliflerinde kral adlarının çevrelendiği oval çerçeveye ne denir?', 'Kartuş', ['Kopya, yani çapraz çerçeve', 'Kanat, kuş kanadı biçiminde sembol', 'Pilon, anıtsal tapınak girişi'], 'Kartuş, firavunun adını koruyucu bir ip halkası içinde gösterir; Champollion kartuşlardaki adlarla çözüme ilerlemiştir.'),
  ('Bir arkeolog üst tabakada Roma sikkesi, alt tabakada Hellenistik seramik buluyor. Bu sıralama neyi gösterir?', 'Normal bir stratigrafik sıralama', ['Tabakaların ters çevrildiğini, yani üst katmanın daha eski olduğunu', 'Sikkelerin yanlış tarihlendiğini, çünkü Roma dönemi Hellenistik dönemden önce gelir', 'Kazının sahte olduğunu, çünkü her tabaka aynı dönemden olmalıdır'], 'Hellenistik dönem Roma\'dan önce gelir; eski eşya altta, yeni eşya üstte olduğundan sıralama beklenen stratigrafiyi yansıtır.'),
  ('Aşağıdakilerden hangisi göreli (bağıl) tarihleme yöntemidir?', 'Stratigrafi', ['Dendrokronoloji, halka kalıplarını eşleştiren yöntem', 'Termolüminesans, ısıtma ışıması ölçümü', 'Radyokarbon, C-14 oranı ölçümü'], 'Stratigrafi yalnızca eskilik sırasını verir; dendrokronoloji, termolüminesans ve radyokarbon ise sayısal yaş verir.'),
  ('Taş-Bakır-Tunç-Demir sıralamasında Kalkolitik hangi iki çağ arasındadır?', 'Neolitik ile Tunç Çağı', ['Paleolitik ile Neolitik', 'Tunç ile Demir', 'Demir Çağı ile Roma'], 'Kalkolitik, Neolitik\'ten sonra, Tunç Çağı\'ndan önce gelen bakırtaş geçiş dönemidir.'),
  ('Göbeklitepe\'nin en eski yapıları günümüzden yaklaşık ne kadar önceye tarihlenir?', '12 bin yıl', ['Yaklaşık 4 bin yıl', 'Yaklaşık 2 bin yıl', 'Yaklaşık 700 yıl'], 'Göbeklitepe\'nin ilk katmanları MÖ 10. binyıl sonuna, yani yaklaşık 12 bin yıl öncesine gider.'),
  ('Çatalhöyük\'ün yerleşim dönemi günümüzden yaklaşık kaç yıl öncesine denk gelir?', '9 bin yıl', ['Yaklaşık 3 bin yıl', 'Yaklaşık 1500 yıl', 'Yaklaşık 500 yıl'], 'Çatalhöyük yaklaşık MÖ 7100-6000 arasında yerleşim görmüştür; bu da günümüzden yaklaşık 8-9 bin yıl öncesine karşılık gelir.'),
  ('Kazıda çıkan buluntunun yaşını belirlemede en güvenilir sonuç nasıl elde edilir?', 'Birden çok yöntemin sonuçlarının karşılaştırılmasıyla', ['Yalnızca tek bir analizle', 'Yalnızca eserin güzelliğine bakarak', 'Yalnızca yazıtın harfi sayısına bakarak'], 'Stratigrafi, seramik ve fiziksel tarihleme sonuçları birbirini doğrulayacak biçimde değerlendirilir.'),
  ('Mezardan çıkan bir tahılın C-14 tarihi için örnek seçerken hangisi en uygundur?', 'Kömürleşmiş tohum', ['Mermer parça', 'Bronz bilezik', 'Seramik kap'], 'Kömürleşmiş tohum, kısa ömürlü organik bir örnek olduğundan güvenilir radyokarbon tarihi sağlar. Mermer ve bronz karbon içermez ya da organik değildir.'),
  ('Kazı alanında toprağın rengindeki ve dokusundaki değişim neyin işareti olabilir?', 'Farklı birikim tabakasının ya da kazılmış bir çukurun', ['Mutlaka bir yangının', 'Mutlaka bir tapınağın', 'Kazı yönteminin hatasının'], 'Toprağın renk ve doku farkı yeni bir tabakayı ya da dolgu çukurunu işaret edebilir; bu yüzden kazıda dikkatle kaydedilir.'),
  ('Arkeolojide "tipoloji" neyi ifade eder?', 'Buluntuların biçim ve üsluba göre sınıflandırılmasını', ['Ağaçların halka sayımını', 'Kayaların radyoaktif ölçümünü', 'Eserlerin satış değerini'], 'Tipoloji, benzer biçimli buluntuları gruplayarak zaman içindeki değişimleri izlemek için kullanılır.'),
  ('Kazıdan sonra bütün buluntuların kaydedilip yayımlanmasının bilimsel önemi nedir?', 'Başka araştırmacıların sonuçları kontrol edip yeniden yorumlayabilmesi', ['Eserlerin fiyatının yükselmesi', 'Kazı bütçesinin artması', 'Kazıların gizli kalması'], 'Kazı kendi başına yıkıcıdır; belge ve yayın, kaybolan bağlamı bilim insanlarına aktaran tek kalıcı kayıttır.'),
  ('Eski bir yerleşimde bulunan ev tabanının altındaki bebek mezarları, arkeologlara öncelikle ne söyler?', 'Gömü adetleri ve yerleşim içi ritüel alışkanlıkları', ['Savaş yöntemleri', 'Para sistemi', 'Tarım takvimi'], 'Ev içi gömüler, topluluğun ölü ile yaşayanı bir arada tutan geleneklerini yansıtır; Çatalhöyük bunun tipik örneğidir.'),
  ('Paleolitik yerleşimlerde ocak izleri ve yanmış kemik bulunması hangi çıkarım için kullanılır?', 'Ateşin denetimli kullanıldığı', ['Tarımın ve hayvancılığın başladığı', 'Yazının kullanıldığı', 'Madeni paranın basıldığı'], 'Ocak kalıntıları, kömür ve yanık kemikler ateşin pişirme ve ısınma için kontrollü kullanıldığını gösterir.'),
  ('Pergamon Zeus Altarı\'nın bugün sergilendiği müze hangisidir?', 'Berlin Pergamon Müzesi', ['British Museum\'un Elgin salonu', 'Louvre\'un Milo Venüsü salonu', 'Bergama Müzesi'], 'Altarın büyük bölümü 19. yüzyılda Berlin\'e taşınmış ve burada yeniden kurulmuştur; Bergama Müzesi\'nde ise yerel buluntular bulunur.'),
  ('Angkor, Ur, Aksum ve Leptis Magna için verilen ülke bilgilerinden hangisi hatalıdır?', 'Angkor - Tayland', ['Ur - Irak', 'Aksum - Etiyopya', 'Leptis Magna - Libya'], 'Angkor Kamboçya\'dadır, Tayland\'da değildir. Diğer eşleştirmeler doğrudur.'),
  ('Aşağıdaki buluntu-yıl çiftleri arasında eskiden yeniye doğru doğru sıralama hangisidir?', 'Rosetta Taşı bulunması - Champollion\'un çözümü - Tutankhamon\'un mezarı', ['Tutankhamon\'un mezarı - Rosetta Taşı bulunması - Champollion\'un çözümü', 'Champollion\'un çözümü - Tutankhamon\'un mezarı - Rosetta Taşı bulunması', 'Rosetta Taşı bulunması - Tutankhamon\'un mezarı - Champollion\'un çözümü'], 'Rosetta 1799\'da bulundu, Champollion 1822\'de çözümü açıkladı, Tutankhamon\'un mezarı ise 1922\'de bulundu.'),
  ('Aşağıdaki keşiflerden hangisi en eskidir?', 'Troya\'da Schliemann\'ın kazısı (1871)', ['Knossos\'ta Evans\'ın kazısı (1900)', 'Tutankhamon\'un mezarı (1922)', 'Göbeklitepe\'de Schmidt\'in kazısı (1995)'], 'Schliemann 1871\'de Troya\'da çalışmaya başlamıştır; diğerleri daha sonradır.'),
  ('Roma\'nın ilk büyük yolu olarak bilinen yol hangisidir?', 'Via Appia', ['Via Egnatia, Balkanlar yoluna dair', 'Via Sebaste', 'Via Maris'], 'Via Appia, MÖ 312\'de sansür Appius Claudius Caecus tarafından Roma\'yı güneye bağlamak için yapılmıştır.'),
  ('Antik tiyatroda koronun dans ettiği yarım daire ya da daire biçimli alana ne ad verilir?', 'Orkestra', ['Skene\'nin yanında yer alan parodos giriş yolu', 'Cavea\'nın üst kuşağı olan diazoma', 'Proskenion\'un önündeki platform'], 'Orkestra, koro ve oyuncuların hareket ettiği alandır; skene arka plandaki sahne binasıdır.'),
  ('Göbeklitepe yaklaşık 12 bin, Stonehenge yaklaşık 5 bin yıllıktır. Göbeklitepe Stonehenge\'ten yaklaşık kaç yıl daha eskidir?', '7 bin yıl', ['Yaklaşık 17 bin yıl', 'Yaklaşık 3 bin yıl', 'Yaklaşık 12 bin yıl'], '12.000 - 5.000 = 7.000 yıl; Göbeklitepe, Stonehenge\'ten yaklaşık yedi bin yıl eskidir.'),
  ('Giza\'daki Büyük Sfenks hangi firavunun piramit kompleksiyle ilişkilendirilir?', 'Khafre', ['Menkaure\'nin kızı', 'Zoser', 'Tutankhamon'], 'Sfenks, Khafre\'nin piramit kompleksi içinde yer alır ve genellikle onun dönemine atfedilir.'),
  ('Birecik Barajı\'nın yapımı sonucunda Zeugma\'nın büyük bölümünün sular altında kalması neyin göstergesidir?', 'Kalkınma projelerinin kültürel mirasa tehdit oluşturabilmesinin', ['Kentin hiç kazılmadığının', 'Kentin Roma\'ya ait olmadığının', 'Kentin zaten yok olmuş olduğunun'], 'Zeugma, baraj gölü nedeniyle zarar görmüş; kurtarma kazıları ancak bir bölümü kurtarabilmiştir.'),
  ('Hasankeyf\'in Ilısu Barajı nedeniyle su altında kalması hangi tartışmayı güçlendirmiştir?', 'Baraj projeleri ile kültürel mirasın korunması arasındaki çatışmayı', ['Köprü yapımının Roma\'ya ait olduğunu', 'Hitit kentinin sulara karıştığını', 'Kentin Mısır\'da yer aldığını'], 'Ilısu Barajı gölü, Dicle kıyısındaki tarihî Hasankeyf\'i örtmüş; anıtların bir kısmı taşınmış, bir kısmı sular altında kalmıştır.'),
  ('Bergama Kralı II. Eumenes\'in yaptırdığı büyük yapı hangisidir?', 'Zeus Altarı', ['Mausoleion, Halikarnassos\'ta', 'Artemis Tapınağı, Efes\'te', 'Celsus Kütüphanesi, Efes\'te'], 'Büyük Altar, II. Eumenes döneminde (MÖ 2. yüzyıl) Pergamon Akropolisi\'nde yapılmıştır.'),
  ('Anadolu\'daki Roma dönemi kentlerinde "bouleuterion" hangi işlevi görür?', 'Kent meclisi toplantısı', ['Gladyatör eğitimi ve gösterisi', 'Su dağıtımı', 'Tahıl depolama'], 'Bouleuterion, kent meclisi (boule) üyelerinin toplandığı kapalı ya da yarı kapalı salondur.'),
  ('Göbeklitepe\'deki en büyük T biçimli dikmelerin yüksekliği yaklaşık kaç metredir?', '5-6 metre', ['Yaklaşık 12-15 metre', 'Yaklaşık 25-30 metre', 'Yaklaşık 1 metre'], 'En büyük dikmeler yaklaşık 5,5 metreye ulaşır ve yüzlerce ton ağırlığındadır; yine de bunlar çakmaktaşı aletlerle yontulmuştur.'),
  ('Kuzey Amerika\'da Clovis mızrak uçlarının uzun süre ne için delil sayıldığı söylenebilir?', 'Amerika\'ya ilk insan göçü', ['Bronz dökümün başlangıcı', 'Tarımın Mısır\'da başlaması', 'Piramit yapımının Amerika\'ya yayılması'], 'Yaklaşık 13 bin yıl öncesine giden Clovis uçları uzun süre Amerika\'ya ilk gelen insanların kültürü sayılmıştır.'),
  ('Ani\'ye "Bin Bir Kilise Şehri" denilmesi neyi anlatır?', 'Çok sayıda kilisenin bulunduğu zengin bir başkenti', ['Hristiyan nüfusun hiç olmadığını', 'Kentin Osmanlı sınırında olduğunu', 'Kentin yalnızca kalesi olduğunu'], 'Ani, Bagratlı Ermeni Krallığı döneminde çok sayıda kilise ve ticaret yapısıyla büyük bir başkent olmuştur.'),
  ('Tarihî bir alanı çok sayıda turist ziyaret ettiğinde yaşanabilecek temel koruma sorunu hangisidir?', 'Aşınma ve fiziksel hasar', ['Yazıtların silinmesi için yasaklanması', 'Kentin yeniden kurulması', 'Sikkelerin çoğalması'], 'Yoğun ziyaret, yürüme, dokunma ve nem nedeniyle zemin, duvar resimleri ve yüzeylerin aşınmasına yol açar; Lascaux örneğinde olduğu gibi.'),
  ('Müzelerde sergilenen replikanın (kopya) kullanılma nedeni hangisi olabilir?', 'Orijinal esere zarar vermeden sergilemek', ['Eserin gerçek yerinden kaldırılmasını sağlamak', 'Sahte eser satmak', 'Müzeyi küçültmek'], 'Replikalar, hassas eserlerin ışıktan ve dokunmadan korunmasını sağlayıp aynı zamanda halka gösterim yapılmasına izin verir.'),
  ('Bir arkeolojik buluntuya ait bilgilerin (kazı defteri, çizim) saklanmasının nedeni nedir?', 'Gelecekte yeniden yorumlanabilmesi', ['Eserin piyasa fiyatının yükselmesini sağlamak', 'Müzenin reklamı', 'Kazının uzatılması'], 'Kazı sırasında yok edilen bağlamı sonradan yeniden kurabilmek için arşiv belgeleri gereklidir.'),
  ('Anadolu\'daki höyüklerin çoğu ova ve nehir kenarlarında bulunur. Bu konumların seçilmesinin ana nedeni nedir?', 'Su ve verimli tarım toprağına yakınlık', ['Savaşlarda saklanmak ve dağlık yerde savunma kolaylığı', 'Madenlere yakınlık', 'Deniz ticareti'], 'Yerleşik topluluklar için su ve ekilebilir toprak belirleyici olmuş, bu yüzden höyükler nehir ve ova çevresinde yoğunlaşmıştır.'),
  ('Antik kentlerde kazılardan çıkan kanalizasyon ve su yolları neyi gösterir?', 'Kentin altyapı ve halk sağlığı düzeyini', ['Savaş stratejilerini ve ordunun örgütlenmesini', 'Dinî yasakları', 'Sikke türlerini'], 'Su ve atık sistemleri, kent planlamasının ve günlük yaşam kalitesinin göstergesidir; İndus ve Roma kentleri örnektir.'),
  ('Hititlerin Kadeş Antlaşması\'nın bir kopyasının bugün BM binasında sergilenmesi neyi simgeler?', 'Dünya diplomasi tarihinde barış antlaşması geleneğinin önemini', ['BM\'nin Hitit başkentinde kurulduğunu', 'Mısır\'ın Birleşmiş Milletler\'i kurduğunu', 'Hititlerin modern ülkeyi yönettiğini'], 'Antlaşmanın Hitit nüshasının kopyası, bilinen en eski yazılı uluslararası barış belgelerinden biri olarak BM\'de sergilenir.'),
  ('Kültepe tabletlerinde görülen faiz, borç ve ortaklık anlaşmaları neyi gösterir?', 'Gelişmiş bir ticaret hukukunu', ['Sadece tarım takvimini ve hava durumunu', 'Yalnız dinî ritüelleri', 'Yalnız savaş kayıtlarını'], 'Tabletler, Orta Tunç Çağı\'nda özel ticaret ve hukukun güvenilir biçimde yazılı hâle getirildiğini gösterir.'),
  ('Urartu yazıtlarının çoğunun kral adı, fetih ve inşa bildirileri içermesi neyi düşündürür?', 'Yazının kralın gücünü ve propagandasını ilan etmek için kullanıldığını', ['Yazının tamamen dinî olduğunu', 'Yazının tarımda kullanıldığını', 'Yazının yalnız mezar için olduğunu'], 'Urartu kitabeleri, kralın zaferlerini ve yapılarını duyuran resmî belgelerdir; bu da siyasi propaganda işlevini gösterir.'),
  ('Lidya\'nın sikke icadının ticaret üzerindeki en önemli etkisi nedir?', 'Ölçülü ve güvenilir ödeme aracı sağlayarak mübadeleyi kolaylaştırması', ['Ticareti tamamen yasaklaması', 'Takasın zorunlu hâle gelmesi', 'Denizcilikte kullanılması'], 'Belirli ağırlık ve damgalı sikke, tartı ve pazarlık gerektirmeden ödeme yapmayı kolaylaştırarak ticareti hızlandırmıştır.'),
  ('Kral Yolu\'nun Sardes-Susa arasındaki mesafe ve ulaşım hızı açısından önemi nedir?', 'Haberleşmeyi çok hızlandırması', ['Denizcilikte kullanılan bir liman yolu olmasını', 'Tarım sulaması', 'Madencilik'], 'Menzil istasyonları ile haberciler uzun mesafeyi günler içinde aşabiliyor, imparatorluğun yönetimini kolaylaştırıyordu.'),
  ('Tutankhamon mezarının bulunuşundan sonra "Mısır çılgınlığı" (Egyptomania) olarak anılan akımın etkisi nedir?', 'Sanat, moda ve mimaride Mısır motiflerinin yaygınlaşması', ['Roma sanatının yükselmesi', 'Çin porselenine ilgi', 'Gotik mimarinin yayılması'], '1922 keşfi sonrası Art Deco gibi akımlarda Mısır motifleri popülerleşmiş, halkın arkeolojiye ilgisi artmıştır.'),
  ('Türkiye\'de korunması gereken arkeolojik alanlara verilen ad hangisidir?', 'Arkeolojik sit', ['Tarım rezervi', 'Milli park, yani doğal koruma alanı', 'Askerî yasak bölge'], 'Kültür ve Tabiat Varlıklarını Koruma Kanunu\'na göre arkeolojik değeri olan alanlar sit statüsü alır ve izinsiz yapılaşmaya kapatılır.'),
  ('Samothrake Nike\'si (Kanatlı Zafer) bugün hangi müzede sergilenmektedir?', 'Louvre', ['British Museum\'un Parthenon salonu', 'Atina Ulusal Arkeoloji Müzesi', 'Vatikan Müzeleri'], 'Fransız Charles Champoiseau\'nun 1863\'te bulduğu heykel Louvre\'da Daru merdiveninin başında durur.'),
  ('Çorum\'daki Alacahöyük\'te kazı sırasında bulunan sfenksli kapı hangi dönemi temsil eder?', 'Hitit İmparatorluk Dönemi', ['Roma İmparatorluk Dönemi\'nin ilk evresi', 'Neolitik Dönem', 'Bizans Dönemi'], 'Alacahöyük Sfenksli Kapısı, Hitit imparatorluk çağına ait anıtsal şehir kapısıdır.'),
  ('Hititlerin başkenti Hattuşa\'nın en yüksek, savunması en güçlü bölümü hangisidir?', 'Büyükkale', ['Yerkapı\'nın alt terasındaki tapınak mahallesi', 'Aşağı Şehir\'deki Büyük Tapınak çevresi', 'Yazılıkaya\'daki kutsal alan'], 'Büyükkale, kralın sarayı ve idari binaların bulunduğu yüksek akropolistir.'),
  ('Tuşpa\'daki (Van Kalesi) Urartu saray ve sarnıçları hangi çağda yapılmıştır?', 'Demir Çağı', ['Neolitik Çağ', 'Roma İmparatorluk Çağı', 'Hellenistik Çağ'], 'Urartu kalesi ve yapıları Demir Çağı\'na, yaklaşık MÖ 9-7. yüzyıllara tarihlenir.'),
  ('Mısır\'da piramit yapımı için taşların taşınmasında en çok hangi doğal yol kullanılmıştır?', 'Nil Nehri', ['Kızıldeniz', 'Libya Çölü\'nün kum yolları', 'Akdeniz kıyı yolu'], 'Taşlar, taşkın dönemlerinde Nil üzerinden gemilerle taşınmış, Wadi el-Jarf papirüsleri de bunu gösterir.'),
  ('Mezopotamya\'da kerpiç ve tuğla yapı kullanımı hangi doğal nedenle yaygındı?', 'Taş ve ağaç kıtlığı', ['Büyük orman bolluğu ve taş eksikliği', 'Dağlık yapı', 'Mermer bolluğu'], 'Mezopotamya ovalarında taş ve ahşap az, kil bol olduğundan yapı malzemesi olarak kerpiç ve pişmiş tuğla kullanılmıştır.'),
  ('Batıklarda bulunan amfora damgalarının arkeolojiye katkısı nedir?', 'Ticaret mallarının kaynağını ve rotasını belirlemek', ['Geminin rengini bulmak', 'Mürettebatın boyunu ölçmek', 'Gemiyi yeniden yüzdürmek'], 'Amfora damgaları ve biçimleri, şarap ya da yağın hangi bölgeden geldiğini ve ticaret ağını gösterir.'),
  ('Sualtında kazı yaparken en önemli koruma önlemi nedir?', 'Buluntuları çıkarmadan önce kayıt ve belgelemeyi yapmak', ['Eserleri hemen suyun dışında kurutmak', 'Eserleri doğrudan güneşe koymak', 'Buluntuları kuma gömmek'], 'Su altı buluntuları çıkarılmadan önce konumları çizilir ve fotoğraflanır; çıkarıldıktan sonra da kontrollü ortamda korunur.'),
  ('Pamukkale travertenlerinin oluşumunu en iyi hangisi açıklar?', 'Kalsiyum bikarbonatlı sıcak suyun yüzeyde kireç çökeltmesi', ['Volkanik külün suyla birleşip donması', 'Tuzlu denizin çekilirken bıraktığı çökeltiler', 'Rüzgârın taşıdığı kumun nemle sertleşmesi'], 'Karbondioksit kaybeden kaynak suyu kalsiyum karbonatı çöktürür; bu çökelme beyaz teras ve havuzları oluşturur.'),
  ('Sidon\'da bulunan ve İstanbul Arkeoloji Müzeleri\'nde sergilenen İskender Lahdi adını neden almıştır?', 'Kabartmalarında Büyük İskender\'in betimlenmesinden', ['İskender\'in cenazesinin içinde taşınmasından', 'Lahdin Büyük İskender\'in mezar odasında bulunmasından', 'Sidon kralının adının İskender olmasından'], 'Lahit, kabartmalarında Büyük İskender\'in savaş ve av sahnelerini gösterdiği için bu adla anılır; sahibinin Sidon Kralı Abdalonymos olduğu düşünülür.'),
  ('Arkeolojide "sondaj" neyi ifade eder?', 'Yerleşimin tabaka düzenini anlamak için açılan küçük deneme çukurunu', ['Bütün höyüğün tek seferde kazılmasını', 'Yüzeyden toplanan buluntuların yaşını ölçmeyi', 'Eserlerin müzeye taşınmasını'], 'Sondaj, derinlik boyunca tabaka sırasını ve buluntu yoğunluğunu görmek için açılan küçük kazıdır; geniş kazının planlanmasına yardımcı olur.'),
  ('Roma askerî kamplarından (castrum) türeyen kentlerde birbirini dik kesen iki ana cadde hangi adlarla bilinir?', 'Cardo ve decumanus', ['Via Sacra ve Via Appia', 'Forum ve basilica', 'Agora ve stoa'], 'Roma kamp planında kuzey-güney yönündeki cardo ile doğu-batı yönündeki decumanus kentin ana eksenlerini oluşturur.'),
  ('Paris\'teki Concorde Meydanı\'nda bulunan Luksor Dikilitaşı Fransa\'ya nasıl gelmiştir?', 'Mısır Valisi Mehmed Ali Paşa\'nın hediyesi olarak', ['Napolyon\'un Mısır seferi sırasında yağmalanarak', 'İngiliz ordusunun Fransa\'ya satmasıyla', 'Büyük İskender\'in Roma\'ya gönderdiği armağanla'], 'Luksor Tapınağı\'ndaki dikilitaş, Mehmed Ali Paşa\'nın armağanı olarak 1836\'da Paris\'e dikilmiştir.'),
  ('Giza\'daki Büyük Piramit yaklaşık hangi yüzyılda inşa edilmiştir?', 'MÖ 26. yüzyıl', ['MÖ 15. yüzyıl, Yeni Krallık dönemi', 'MÖ 5. yüzyıl, Pers dönemi', 'MS 1. yüzyıl, Roma dönemi'], 'Khufu\'nun piramidi Eski Krallık\'ta, yaklaşık MÖ 2560 dolaylarında yapılmıştır.'),
  ('Tutankhamon\'un mezarı yaklaşık hangi çağda yapılmıştır?', 'MÖ 14. yüzyıl', ['MÖ 26. yüzyıl, piramit çağı', 'MÖ 4. yüzyıl, Ptolemaios dönemi', 'MS 3. yüzyıl, Roma dönemi'], 'Tutankhamon yaklaşık MÖ 1332-1323 arasında hüküm sürmüş Yeni Krallık firavunudur; mezarı bu dönemden kalmadır.'),
  ('Eski Mısır\'da piramit yapımı hangi dönemde terk edilip Kral Vadisi\'ne geçilmiştir?', 'Yeni Krallık', ['Eski Krallık, piramit çağının başlangıcında', 'Geç Dönem, Pers hâkimiyetinde', 'Roma dönemi, imparator yönetiminde'], 'Eski ve Orta Krallık\'ta piramitler yapılırken, Yeni Krallık firavunları kayaya oyulan gizli vadi mezarlarını tercih etmiştir.'),
  ('Bir yüzey araştırmasında Roma dönemi seramikleri ve su kemeri izleri bulan araştırmacı hangi sonuca varmalıdır?', 'Bölgede Roma döneminde yerleşim ve su altyapısı bulunduğuna', ['Bölgenin yalnızca Neolitik olduğuna', 'Bölgede hiç yerleşim olmadığına', 'Bölgenin Pers satraplığı merkezi olduğuna'], 'Seramik ve su kemeri gibi yapı izleri, bölgede Roma dönemi yerleşim ve su yönetimi bulunduğunu düşündürür.'),
];
